const API='/api';
const state={page:'home',status:null,config:null,runs:[],reviewDate:new Date().toISOString().slice(0,10),review:'',latest:null,factorLatest:null,compositeLatest:null,intradayLatest:null,intradayAnalytics:null,busy:false};
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
async function api(path,opt={}){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),opt.timeout??15000);try{const fetchOpt={headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt};if(!fetchOpt.signal)fetchOpt.signal=controller.signal;const r=await fetch(API+path,fetchOpt);if(!r.ok){let msg=r.statusText;try{const body=await r.json();msg=body.error||body.detail||msg}catch{}throw Error(`${r.status} ${msg}`)}return r.status===204?null:r.json()}finally{clearTimeout(timeout)}}
function toast(msg,kind=''){const e=document.querySelector('#toast');e.textContent=msg;e.className='show '+kind;setTimeout(()=>e.className='',3500)}
function cap(k){const caps=state.status?.capabilities||{};const aliases={factor_evaluate:['factor_evaluate','factors','factor'],data_update:['data_update','data'],predict:['predict','prediction'],composite_factor:['composite_factor','factor'],intraday_predict:['intraday_predict','predict']};const c=aliases[k]?.map(x=>caps[x]).find(v=>v!==undefined);return c===true||c?.available===true||c?.enabled===true}
function capReason(k){const c=state.status?.capabilities?.[k];return typeof c==='object'?(c.reason||c.detail||'当前环境不可用'):'后端未声明此能力'}
function can(k){if(cap(k))return true;toast(`${k}：${capReason(k)}`,'error');return false}
function val(path,fall=''){let x=state.config;for(const p of path.split('.'))x=x?.[p];return x??fall}
function isoDate(x){if(!x)return '';x=String(x);return /^\d{8}$/.test(x)?`${x.slice(0,4)}-${x.slice(4,6)}-${x.slice(6)}`:x}
function fmtTime(x){if(!x)return '—';try{return new Date(x).toLocaleString('zh-CN',{hour12:false})}catch{return x}}
function shell(title,sub,body,actions=''){return `<div class="hero"><div><h1>${title}</h1><p>${sub}</p></div><div class="hero-actions">${actions}</div></div>${body}`}
function btn(text,id,cls='btn'){return `<button class="${cls}" id="${id}">${text}</button>`}
function activeDataRun(){return state.runs.find(r=>r.kind==='data_update'&&['queued','running'].includes(r.status))}
function latestDataRun(){const runs=state.runs.filter(r=>r.kind==='data_update').slice().sort((a,b)=>String(b.created_at||b.started_at||'').localeCompare(String(a.created_at||a.started_at||'')));return activeDataRun()||runs.find(r=>!r.params?.validate_only&&r.scope!=='validation')||runs[0]}
function dataStatusLabel(status){return ({updated:'已更新',completed:'已完成',partial:'部分更新',waiting:'等待下一批数据',deferred:'数据源尚未发布',failed:'更新失败',error:'更新失败',planned:'待执行',unchanged:'已是最新',up_to_date:'已是最新',skipped:'本次未更新',running:'更新中'})[status]||'未核验'}
function dataFreshness(){
  const d=state.status?.data||{},update=d.update_status||{},intraday=d.intraday||{},daily=update.daily||{};
  const latest=d.latest_date||daily.latest_available_date,observed=intraday.latest_timestamp;
  const dailyTarget=daily.target,intradayTarget=update.intraday?.cutoff;
  const failed=Number(intraday.failure_count)||0,codes=intraday.latest_codes,total=intraday.codes;
  const coverage=codes!=null?`最新时点覆盖 ${codes}${total!=null?' / '+total:''} 只`:'最新时点覆盖待核验';
  const lag=latest&&dailyTarget&&String(latest).replaceAll('-','')<String(dailyTarget).replaceAll('-','');
  const lastRun=latestDataRun(),lastSync=lastRun?.finished_at||d.last_updated;
  return {cards:`<div class="kpi-grid compact data-kpis">${metricCard('已落盘日线',latest?isoDate(latest):'未核验',dailyTarget?'自动补齐目标 '+isoDate(dailyTarget):'自动目标等待检查',lag?'amber':'cyan')}${metricCard('已落盘分时 bar',observed||'未核验',observed?coverage:'尚未读取面板实际时间，不能判断新鲜度',failed?'amber':'green')}${metricCard('已保存日线面板',d.panel_count??'—','份')}${metricCard('最近更新任务结束',lastSync?fmtTime(lastSync):'暂无记录',lastRun?`${lastRun.id} · ${statusNames[lastRun.status]||lastRun.status}`:'面板文件记录')}</div>${lag?`<p class="notice warn data-lag">日线已保存至 ${esc(isoDate(latest))}，自动目标为 ${esc(isoDate(dailyTarget))}，仍有已收盘交易日待补齐。</p>`:''}`,
    details:`<div class="data-freshness-grid"><div class="freshness-card"><span class="freshness-icon">◷</span><div><b>分时数据</b><strong>${esc(observed||'实际数据时间未核验')}</strong><small>${esc(coverage)}${failed?' · 失败 '+failed+' 只':''}</small><small>自动目标：${esc(intradayTarget||'等待检查')} · ${esc(dataStatusLabel(update.intraday?.status))}</small><small>只补齐已完成的 30 分钟 bar。目标时间不代表已完成更新。</small></div></div><div class="freshness-card"><span class="freshness-icon">▣</span><div><b>日线数据</b><strong>${esc(latest?isoDate(latest):'实际数据日期未核验')}</strong><small>自动目标：${esc(dailyTarget?isoDate(dailyTarget):'等待检查')} · ${esc(dataStatusLabel(daily.status))}</small><small>先补齐已收盘交易日；当天尚未收盘不影响补齐历史日线。</small></div></div></div>`};
}
function renderData(){const freshness=dataFreshness(),run=latestDataRun();return shell('数据更新','自动检查日线与分时的实际进度，补齐最新可用数据；盘中先更新已完成的分时 bar。',`<div id="data-status-overview">${freshness.cards}</div><div class="panel data-auto-panel"><div class="panel-head"><h2>自动更新</h2><span class="pill ok">默认：自动判断</span></div><div id="data-freshness-detail">${freshness.details}</div><div class="actions"><button class="btn ghost" id="validate-data">检查数据状态</button><button class="btn primary" id="start-data">自动更新最新数据</button></div><details class="advanced-date"><summary>高级：指定历史日期（通常无需填写）</summary><div class="field"><label>更新至交易日</label><input id="data-date" type="date" value=""><small>留空则自动补齐最新可用数据；仅重跑历史日时填写。</small></div></details></div><div class="panel"><h2>更新进度与日志</h2><div id="data-run-output" aria-live="polite">${run?jobProgress(run):empty('暂无更新记录','启动后在这里显示分时与日线两个阶段的状态')}</div></div>`)}
function refreshDataView(){if(state.page!=='data')return;const freshness=dataFreshness();const overview=document.querySelector('#data-status-overview'),detail=document.querySelector('#data-freshness-detail');if(overview)overview.innerHTML=freshness.cards;if(detail)detail.innerHTML=freshness.details;syncDataControls()}
function syncDataControls(){if(state.page!=='data')return;const active=activeDataRun();for(const id of ['start-data','validate-data']){const button=document.querySelector('#'+id);if(button)button.disabled=Boolean(active)||state.busy}}

function renderFactors(){const f=state.config?.factor||{};return shell('因子与 EMA 实验','调整参数，比较 Kronos、SET10 和组合在最近交易日的实际表现',`<div class="panel"><h2>评估参数</h2><div class="grid grid-4">${numberField('Kronos 权重','f-kronos',f.kronos_weight??.45,0,1,.01)}${numberField('SET10 权重','f-set10',f.set10_weight??.55,0,1,.01)}${numberField('Kronos EMA 衰减','f-ema-k',f.ema_kronos??.88,0,.999,.01)}${numberField('SET10 EMA 衰减','f-ema-s',f.ema_set10??.88,0,.999,.01)}${numberField('统计窗口（交易日）','f-lookback',f.lookback_days??10,1,120,1)}${numberField('持有期（交易日）','f-holding',f.holding_days??2,1,10,1)}${numberField('Top K 股票数','f-topk',f.top_k??100,1,200,1)}${numberField('卖出阈值（跌出排名）','f-exitrank',f.exit_rank??1000,1,100000,1)}${numberField('浪型门控 α（0=关闭）','f-gatealpha',f.gate_alpha??0.65,0,0.99,.01)}<div class="field"><label>缠论持仓规则</label><select id="f-gatemode"><option value="up_only" ${(f.gate_mode??'up_only')==='up_only'?'selected':''}>仅上涨持仓</option><option value="non_down" ${f.gate_mode==='non_down'?'selected':''}>仅下跌清仓</option><option value="off" ${f.gate_mode==='off'?'selected':''}>不门控</option></select></div>${numberField('单边综合成本（bps）','f-fee',f.fee_bps??10,0,1000,1)}<div class="field"><label>门控信号</label><select id="f-gatesource"><option value="chan" ${(f.gate_source??'chan')==='chan'?'selected':''}>缠论因果阶段</option><option value="wave" ${(f.gate_source)==='wave'?'selected':''}>浪型 EMA</option></select></div><div class="field"><label>组合因子</label><select id="f-group"><option value="1,3,5,10">E1 + E3 + E5 + E10（等权）</option><option value="1,3">E1 + E3（等权）</option><option value="1,5,10">E1 + E5 + E10（等权）</option><option value="custom">自定义组合</option></select></div><div class="field f-custom-factor"><label>自定义 E 序列</label><input id="f-custom-horizons" value="1,3,5" placeholder="例如 1,3,5"></div><div class="field f-custom-factor"><label>对应权重</label><input id="f-custom-weights" value="0.2,0.3,0.5" placeholder="例如 0.2,0.3,0.5"></div><div class="field"><label>Kronos 模型</label><select id="f-ksource"><option value="daily" ${(f.kronos_source??'composite')==='daily'?'selected':''}>日线 Kronos（rp10 冻结曲线）</option><option value="intraday" ${f.kronos_source==='intraday'?'selected':''}>分时 Kronos（15:00 信号）</option><option value="composite" ${(f.kronos_source??'composite')==='composite'?'selected':''}>组合因子（E1+E3+E5+E10 等权）</option></select></div><div class="field"><label>评估截至信号日</label><input id="f-date" type="date" value="${esc(isoDate(state.status?.data?.latest_date)||state.reviewDate)}"></div></div><p class="muted">纯 E1/E3/E5/E10 模式忽略 SET10 权重与 EMA，只按四个期限的百分位等权排名。最多 TopK 个持仓，只从当前前 TopK 补空位；收盘决策、次日开盘执行。门控是否启用由“缠论持仓规则”明确选择，α 只属于浪型参数。纯组合从现有冻结曲线首日回放至所选日期；统计窗口和固定持有期不参与其账户收益计算。</p><div class="actions">${btn('恢复已保存配置','load-config','btn ghost')}${btn('保存为默认参数','save-config')}${btn('运行因子评估','run-factors','btn primary')}${btn('运行组合因子','run-composite','btn primary')}</div></div><div class="panel"><div class="panel-head"><h2>因子表现</h2><span class="muted">真实行情与冻结 Kronos 曲线</span></div><div id="factor-output">${empty('暂无因子评估结果','点击运行，结果将保存在此页和产物中心')}</div></div><div class="panel"><div class="panel-head"><h2>组合因子结果</h2><span class="muted">可选择 E1–E10 并追踪稳定性</span></div><div id="composite-output">${state.compositeLatest?.available?compositeResult(state.compositeLatest.result):empty('暂无组合因子结果','选择组合后运行')}</div></div>`)}
function renderTrendLegacyPanels(){return `<div class="panel"><div class="panel-head"><h2>大盘浪型阶段（艾略特：推动 1-3-5 / 调整 A-C）</h2><span class="muted">宏观因子卡状态量 · 与个股横截面因子正交</span></div><div id="market-wave-output">${empty('尚未加载','等待大盘浪型因子数据')}</div></div><div class="panel"><div class="panel-head"><h2>缠论阶段引擎（门控主信号）</h2><span class="muted">分型→笔→中枢 · MACD背驰 · 因果确认</span></div><div id="chan-output">${empty('尚未加载','等待缠论阶段数据')}</div></div><div class="panel"><div class="panel-head"><h2>多级别缠论阶段（5F–30F–D / 30F–D–W / D–W–M）</h2><span class="muted">分型→笔→中枢 · 三级别共振 · 未来阶段三分类</span></div><div class="grid grid-4"><div class="field"><label>级别组合</label><select id="chan-combo"><option value="5F-30F-D" ${(state.chanCombo??'5F-30F-D')==='5F-30F-D'?'selected':''}>5F–30F–D（主）</option><option value="30F-D-W" ${state.chanCombo==='30F-D-W'?'selected':''}>30F–D–W</option><option value="D-W-M" ${state.chanCombo==='D-W-M'?'selected':''}>D–W–M</option></select></div><div class="field"><label>标签口径</label><input value="未来5日路径型：持续上涨/持续下跌/盘整" disabled></div><div class="field"><label>验证方式</label><input value="walk-forward · balanced accuracy" disabled></div><div class="field"><label>数据</label><input value="5F 篮子2020+ · 30F全市场2000+ · HS300 2005+" disabled></div></div><div class="actions" style="margin-top:10px">${btn('运行多级别验证','run-chan-multi','btn primary')}</div><div id="chan-multi-output">${empty('尚未加载','等待多级别缠论数据')}</div></div>`}
function renderTrends(){return shell('趋势分析','从大盘结构到行业强弱，观察趋势、回试与级别变化',window.TrendAnalysis.page(renderTrendLegacyPanels()))}
function renderRuns(){return shell('运行日志与产物中心','查看每次更新、实验和预测的状态，以及可下载的真实产物',`<div class="grid grid-2"><div class="panel"><h2>运行记录</h2><div class="actions" style="margin:0 0 13px">${btn('刷新','refresh-runs','btn ghost')}</div><div id="runs-list">${runList(state.runs)}</div></div><div class="panel"><h2>产物</h2><div id="artifacts-list" class="empty-state"><div><b>正在读取</b></div></div></div></div><div class="panel"><h2>运行详情</h2><div id="run-detail" class="empty-state"><div><b>选择一条运行记录</b><span>日志输出将显示在这里</span></div></div></div>`)}
function runList(rs){if(!rs?.length)return '<div class="empty-state"><div><b>暂无运行记录</b><span>提交数据更新、回测或预测后会出现在这里</span></div></div>';return rs.map(r=>`<div class="run-card" data-run="${esc(r.id||r.run_id)}"><div class="run-head"><b>${esc(r.kind||r.type||'运行')}</b><span class="pill ${r.status==='completed'?'ok':r.status==='failed'?'warn':''}">${esc(r.deferred?'等待官方日线':(statusNames[r.status]||r.status||'unknown'))}</span></div><small>${esc(r.id||r.run_id||'')} · ${fmtTime(r.created_at||r.started_at)}</small></div>`).join('')}
function paramsData(){const date=document.querySelector('#data-date')?.value;return date?{date}:{}}
function paramsFactor(){return Object.fromEntries([['kronos_weight','f-kronos'],['set10_weight','f-set10'],['ema_kronos','f-ema-k'],['ema_set10','f-ema-s'],['lookback_days','f-lookback'],['holding_days','f-holding'],['top_k','f-topk'],['exit_rank','f-exitrank'],['gate_alpha','f-gatealpha'],['gate_source','f-gatesource'],['gate_mode','f-gatemode'],['fee_bps','f-fee'],['kronos_source','f-ksource'],['date','f-date']].map(([k,id])=>[k,document.querySelector('#'+id)?.value]).filter(([,v])=>v!==''&&v!=null))}
function paramsComposite(){const g=document.querySelector('#f-group')?.value||'1,3,5,10';return {horizons:g==='custom'?(document.querySelector('#f-custom-horizons')?.value||'1,3,5,10'):g,weights:g==='custom'?(document.querySelector('#f-custom-weights')?.value||'equal'):'equal',top_k:document.querySelector('#f-topk')?.value||10,lookback_days:document.querySelector('#f-lookback')?.value||5,date:document.querySelector('#f-date')?.value}}
function paramsPredict(){return {date:document.querySelector('#p-date')?.value||isoDate(state.status?.data?.latest_date)}}
async function loadArtifacts(){try{const a=await api('/artifacts');const arr=listPayload(a,'artifacts');document.querySelector('#artifacts-list').innerHTML=arr.length?arr.map(x=>`<div class="artifact"><span>${esc(x.name||x.filename||x.id)}</span><a href="${API}/artifacts/${encodeURIComponent(x.id)}" target="_blank">下载</a></div>`).join(''):'<div class="empty-state"><div><b>暂无产物</b></div></div>'}catch(e){document.querySelector('#artifacts-list').innerHTML='<div class="notice error">'+esc(e.message)+'</div>'}}
function renderPage(push=true){const raw=(location.hash||'#home').slice(1);const requested=raw==='predict'?'daily_predict':raw;state.page=['home','data','factors','trends','chan_cases','daily_predict','intraday_predict','history','runs'].includes(requested)?requested:'home';document.querySelectorAll('.page').forEach(e=>e.classList.remove('active'));const el=document.querySelector('#page-'+state.page);if(!el)return;el.classList.add('active');const render={home:renderHome,data:renderData,factors:renderFactors,trends:renderTrends,chan_cases:()=>window.ChanCases.page(),daily_predict:renderDailyPredict,intraday_predict:renderIntradayPredict,history:renderHistory,runs:renderRuns}[state.page];el.innerHTML=render();document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===state.page));const crumb=document.querySelector('#crumb');if(crumb)crumb.textContent={home:'研究首页',data:'数据更新',factors:'因子与 EMA',trends:'趋势分析',chan_cases:'缠论 / 经典案例分析',daily_predict:'Kronos 日模型',intraday_predict:'Kronos 分时模型',history:'历史行情',runs:'运行日志'}[state.page];bindPage();if(state.page==='runs')loadArtifacts();if(state.page==='factors'&&state.factorLatest?.available)resultInto(document.querySelector('#factor-output'),state.factorLatest);if(state.page==='trends'){window.TrendAnalysis.mount();loadMarketWave();loadChanPhase();loadChanMulti()}if(state.page==='chan_cases')window.ChanCases.mount();if(state.page==='factors'&&state.compositeLatest?.available){const co=document.querySelector('#composite-output');if(co)co.querySelectorAll('.ifchart').forEach(b=>ifcRender(b))}if(state.page==='daily_predict'){if(state.latest)resultInto(document.querySelector('#candidate-output'),state.latest);loadChampion()}if(state.page==='intraday_predict'){loadIntradayAnalytics();loadPaperAccount()}if(state.page==='history')loadVolumeHistory()}

function bindPage(){const on=(id,fn)=>document.querySelector('#'+id)?.addEventListener('click',()=>Promise.resolve().then(fn).catch(e=>toast(e.message,'error')));on('quick-data',()=>location.hash='#data');on('quick-predict',()=>location.hash='#daily_predict');on('quick-runs',()=>location.hash='#runs');on('start-data',()=>startJob('data_update',paramsData(),'#data-run-output'));on('validate-data',()=>startJob('data_update',{...paramsData(),validate_only:true},'#data-run-output'));on('run-factors',()=>startJob('factor_evaluate',paramsFactor(),'#factor-output'));on('run-composite',()=>startJob('composite_factor',paramsComposite(),'#composite-output'));on('run-intraday',()=>startJob('intraday_predict',{top_k:Number(document.querySelector('#intraday-topk')?.value||5)},'#intraday-output'));on('refresh-intraday',refreshIntraday);on('start-predict',()=>startJob('predict',paramsPredict(),'#candidate-output'));on('export-predict',()=>downloadText('prediction.json',JSON.stringify(state.latest||{},null,2)));on('load-config',async()=>{state.config=await api('/config');renderPage(false);toast('已恢复保存的默认参数')});on('run-chan-multi',()=>startJob('chan_multi',{combo:document.querySelector('#chan-combo')?.value||state.chanCombo||'5F-30F-D'},'#chan-multi-output'));document.querySelector('#chan-combo')?.addEventListener('change',()=>loadChanMulti());on('save-config',async()=>{const {date,...factor}=paramsFactor();state.config=await api('/config',{method:'PUT',body:JSON.stringify({factor})});toast('默认参数已保存')});on('refresh-runs',async()=>{state.runs=listPayload(await api('/runs'),'runs');renderPage(false)});document.querySelectorAll('[data-run]').forEach(e=>e.addEventListener('click',()=>showRun(e.dataset.run)));const cg=document.querySelector('#f-group');const toggleCustom=()=>document.querySelectorAll('.f-custom-factor').forEach(e=>e.hidden=cg?.value!=='custom');cg?.addEventListener('change',toggleCustom);toggleCustom();bindFactorStockInteractions();bindIntradayInteractions();if(state.page==='data'){syncDataControls();const active=activeDataRun();if(active)resumeDataJob(active)}}
function downloadText(name,text){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain'}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
async function refresh(){try{state.status=await api('/status')}catch(e){state.status=null;toast('无法连接后端：'+e.message,'error')}try{state.config=await api('/config')}catch{}try{const r=await api('/runs');state.runs=listPayload(r,'runs')}catch{}try{state.latest=await api('/results/latest')}catch{state.latest=null}try{state.factorLatest=await api('/factors/latest')}catch{state.factorLatest=null}try{state.compositeLatest=await api('/composite/latest')}catch{state.compositeLatest=null}try{state.intradayLatest=await api('/intraday/latest')}catch{state.intradayLatest=null}updateTop();renderPage(false)}
function listPayload(x,key){return Array.isArray(x)?x:(x?.[key]||x?.items||x?.results||[])}
function updateTop(){const side=document.querySelector('#side-status');if(side)side.textContent=state.status?'后端已连接':'后端不可用';const badge=document.querySelector('#gpu-badge');if(badge){badge.textContent=state.status?'● 已连接':'● 离线';badge.className='badge '+(state.status?'':'muted')}const demo=document.querySelector('#demo-badge');if(demo)demo.hidden=!state.status?.demo;const clock=document.querySelector('#clock');if(clock)clock.textContent=new Date().toLocaleDateString('zh-CN')}
window.api=api;window.esc=esc;
window.addEventListener('hashchange',()=>renderPage());window.addEventListener('DOMContentLoaded',()=>{document.querySelector('#refresh')?.addEventListener('click',refresh);renderPage();refresh()});

// Structured, visual result layer.  Keep raw JSON out of the primary workflow.
function metricCard(label,value,sub='',tone=''){return `<div class="metric"><label>${esc(label)}</label><strong class="${tone}">${esc(value??'—')}</strong><small>${esc(sub)}</small></div>`}
function latestSummary(){return state.latest?.summary||null}
function auditChart(s){const a=s?.data_audit||{};const vals=[['股票数',a.stocks||0],['数据行',a.rows||0],['信号日',a.kronos?.available_signal_sessions||0],['Kronos行',a.kronos?.accepted_rows||0]];const max=Math.max(...vals.map(x=>Number(x[1])||0),1);return `<div class="chart-card"><div class="chart-title">数据审计规模</div><div class="bars">${vals.map(([k,v])=>`<div class="bar-row"><span>${esc(k)}</span><div class="bar-track"><i style="width:${Math.max(3,Number(v)/max*100)}%"></i></div><b>${Number(v).toLocaleString('zh-CN')}</b></div>`).join('')}</div></div>`}
function exposureChart(s){const exp=Number(s?.planned_exposure??0);const w=Math.max(0,Math.min(100,exp*100));return `<div class="chart-card"><div class="chart-title">计划暴露</div><div class="health"><div class="health-track"><i style="width:${w}%"></i></div><b>${(exp*100).toFixed(1)}%</b></div><small class="muted">${s?.status==='NO_TRADE'?'市场状态或门槛未满足，保持空仓':'按 shadow plan 执行'}</small></div>`}
function renderHome(){const d=state.status?.data||{};const s=latestSummary();const caps=state.status?.capabilities||{};return shell('研究首页','先看数据是否新鲜，再复盘、调参、推演；每一步都有运行记录',`<div class="kpi-grid">${metricCard('最新日线面板',d.latest_date||'—',d.last_updated?fmtTime(d.last_updated):'等待同步','cyan')}${metricCard('下一交易日',s?.next_trade_date||'—',s?.signal_date?`信号日 ${s.signal_date}`:'尚无预测','green')}${metricCard('预测状态',s?.status||'—',s?.market_state?`市场：${s.market_state}`:'等待影子结果',s?.status==='NO_TRADE'?'amber':'green')}${metricCard('计划暴露',s?`${(Number(s.planned_exposure||0)*100).toFixed(1)}%`:'—',s?.target_names!=null?`${s.target_names} 个目标`:'尚无目标',s?.planned_exposure?'cyan':'amber')}</div><div class="home-grid"><div class="panel"><div class="panel-head"><h2>今日工作流</h2><span class="pill ok">${state.status?'后端已连接':'连接中'}</span></div><div class="workflow"><a class="step done" href="#data"><b>01 数据更新</b><span>${d.latest_date||'未读取'} · K 线 / 指数</span></a><a class="step" href="#factors"><b>02 因子与 EMA</b><span>调整参数并保存实验配置</span></a><a class="step" href="#daily_predict"><b>03 日模型推演</b><span>生成下一交易日 shadow plan</span></a></div><div class="quick spaced">${btn('更新数据','quick-data','btn primary')}${btn('执行预测','quick-predict','btn primary')}${btn('运行日志','quick-runs','btn')}</div></div><div class="panel"><h2>结果概览</h2>${s?`<div class="result-grid">${auditChart(s)}${exposureChart(s)}</div><div class="notice ${s.status==='NO_TRADE'?'warn':''}">${s.status==='NO_TRADE'?'当前影子链路给出 NO_TRADE，未生成目标组合。':'已生成下一交易日 shadow plan。'}</div>`:'<div class="empty-state"><div><b>暂无预测结果</b><span>完成一次预测后这里会显示审计规模与暴露图</span></div></div>'}</div></div><div class="panel"><div class="panel-head"><h2>最近运行</h2><a class="text-link" href="#runs">查看全部</a></div>${runList(state.runs.slice(0,4))}</div>`)}
function renderDailyPredict(){const p=state.config?.predict||{};const s=latestSummary();const defaultDate=isoDate(state.status?.data?.latest_date)||state.reviewDate;return shell('Kronos 日模型','独立运行日线模型，使用最近完整交易日数据生成下一交易日计划。',`<div class="panel predict-auto-bar"><div class="panel-head"><h2>日模型运行方式</h2><span class="pill ok">默认：自动取最新</span></div><p class="muted">日模型使用最近完整日线；分时模型已移到独立页面，可按盘中最新 30 分钟 bar 单独运行。</p><div class="actions">${btn('导出最近结果','export-predict','btn ghost')}</div><details class="advanced-date"><summary>高级：指定日模型信号日（通常无需填写）</summary><div class="field"><label>信号日（不是目标日）</label><input id="p-date" type="date" value=""><small>留空时由后端根据日线面板自动选择 ${esc(defaultDate)}。</small></div></details></div><section class="model-column daily-model daily-page-column"><div class="model-heading"><div><span class="model-kicker">DAILY KRONOS</span><h2>日模型 · 下一交易日计划</h2><p>因子、EMA、市场状态与候选组合</p></div><span class="pill">${esc(p.model||'rp10_full_bdecdf09')}</span></div><div class="model-actions">${btn('生成日模型结果','start-predict','btn primary')}</div><div class="kpi-grid compact">${metricCard('信号日',s?.signal_date||'—','最新完整日线')}${metricCard('目标交易日',s?.next_trade_date||'—','交易日历解析','green')}${metricCard('市场状态',s?.market_state||'—','策略判断')}${metricCard('目标数量',s?.target_names??'—','候选组合数量',s?.target_names?'cyan':'amber')}</div><div class="model-result" id="candidate-output">${s?predictionResult(s):empty('暂无日模型结果','点击“生成日模型结果”')}</div></section><div class="panel champion-panel"><div class="panel-head"><h2>冠军模型工作簿（2026-09-03）</h2><span class="muted">可读摘要 · 原始 Excel 口径</span></div><div id="champion-workbook">${empty('读取工作簿摘要中','包含总览、Top 股票、行业和审计')}</div></div>`)}
function renderIntradayPredict(){return shell('Kronos 分时模型','独立运行盘中模型，按最新已完成 30 分钟 bar 推演，并展示行业排名、市场曲线与持仓提醒。',`<section class="model-column intraday-model intraday-page-column"><div class="model-heading"><div><span class="model-kicker">INTRADAY KRONOS</span><h2>分时模型 · 最新盘中推演</h2><p>最新 30 分钟 bar、行业排名与市场曲线</p></div><span class="pill">KRN-260912-ID30</span></div><div class="model-actions">${btn('运行最新分时预测','run-intraday','btn primary')}${btn('刷新分时结果','refresh-intraday','btn ghost')}<label class="inline-field">Top <input id="intraday-topk" type="number" min="1" max="100" value="5"></label></div><div id="intraday-output">${state.intradayLatest?.available?intradayResult(state.intradayLatest.result):empty('暂无分时动态结果','使用最新已完成 bar 后显示买入窗口、卖出条件与稳定性')}</div><div class="intraday-analytics-block"><div class="panel-head"><h3>盘中市场与行业</h3><span class="muted" id="intraday-analytics-asof">自动读取最新快照</span></div><div id="intraday-analytics">${state.intradayAnalytics?intradayAnalyticsResult(state.intradayAnalytics):empty('等待分时快照','运行分时预测后读取行业排名和市场曲线')}</div></div><div class="panel-head position-head"><h3>纸上账户 · 模拟持仓</h3><span class="muted">本金 / 卖出平仓 / 胜率记录 · T+1 · 不下实盘</span></div><div id="paper-account">${paperAccountBlock()}</div><form id="intraday-position-form" class="position-form"><label>股票代码<input id="position-code" list="intraday-codes" placeholder="例如 000001.SZ" required></label><datalist id="intraday-codes"></datalist><label>股数<input id="position-shares" type="number" min="1" step="1" value="100" required></label><label>成本价<input id="position-price" type="number" min="0.001" step="0.001" placeholder="选中股票后自动带入" required></label><label>买入日期<input id="position-date" type="date" value="${esc(new Date().toISOString().slice(0,10))}" required></label><button class="btn primary" type="submit">加入模拟持仓</button></form><div id="position-form-state" class="muted"></div></section>`)}
function renderPredict(){return renderDailyPredict()}

function resultInto(el,r){if(!el)return;el.classList.remove('empty-state','candidate-placeholder');const s=r?.result?.summary||r?.result||r?.summary||r?.output||r;if(s?.kind==='factor_evaluation'||s?.metrics)el.innerHTML=factorResult(s);else if(s?.kind==='kronos_composite_factor')el.innerHTML=compositeResult(s);else if(s?.kind==='intraday_timing')el.innerHTML=intradayResult(s);else if(s?.signal_date&&s?.status)el.innerHTML=predictionResult(s);else if(s?.status)el.innerHTML=jobProgress(s);else el.innerHTML=empty('暂无可显示结果',s?.reason||'结果文件尚未生成');el.querySelectorAll('.ifchart').forEach(b=>ifcRender(b));if(el.querySelector('#gate-chart'))renderGateChart(el)}

async function showRun(id){try{const r=await api('/runs/'+encodeURIComponent(id));const el=document.querySelector('#run-detail');if(el){el.classList.remove('empty-state');updateRunOutput(el,jobProgress(r)+(r.result?factorResult(r.result):''))}}catch(e){toast(e.message,'error')}}

function empty(title,detail=''){return `<div class="empty-state"><div><b>${esc(title)}</b><span>${esc(detail)}</span></div></div>`}
function numberField(label,id,value,min,max,step){return `<div class="field"><label>${esc(label)}</label><input id="${id}" type="number" value="${value}" min="${min}" max="${max}" step="${step}"></div>`}
function num(v,d=4){return v==null||v===''||!Number.isFinite(Number(v))?'—':Number(v).toFixed(d)}
function pct(v){return v==null||v===''||!Number.isFinite(Number(v))?'—':(Number(v)*100).toFixed(2)+'%'}
function predictionResult(s){return `<div class="summary-card"><div class="prediction-signal"><strong class="${s.status==='NO_TRADE'?'amber':'green'}">${esc(s.status)}</strong><span>${esc(s.signal_date)} → ${esc(s.next_trade_date)}</span></div><p>${s.status==='NO_TRADE'?'本次预测已完成。策略未通过入场门槛，因此目标组合为空，计划暴露为 0。下方股票排序仍可用于研究。':'本次策略计划已生成。候选与权重以本次产物为准。'}</p><div class="grid grid-3">${metricCard('计划暴露',pct(s.planned_exposure),'策略计划')}${metricCard('目标数量',s.target_names??0,'只股票')}${metricCard('市场状态',s.market_state||'—','策略判断')}</div>${(s.promotion_blockers||[]).map(x=>`<p class="notice">${esc(x)}</p>`).join('')}<div class="actions"><a class="text-link" href="#runs">查看运行与产物</a></div></div>`}
function factorResult(s){
if(s.engine_version!=='causal_cash_book_v2')return '<p class="notice">旧版结果：使用旧持仓与收益口径，请重新运行后比较。</p>'+legacyFactorResult(s);
const daily=s.daily_metrics||[],p=s.effective_parameters||{},rows=s.metrics||[],mode=({off:'不门控',non_down:'仅下跌清仓',up_only:'仅上涨持仓'})[s.gate_mode]||s.gate_mode;
return `<div class="panel-head"><span class="pill ok">${esc(s.score_source==='pure_e1e3e5e10'?'纯 E1+E3+E5+E10':'资金账户回测')}</span><span class="pill">${esc(mode)}</span><span class="muted">${esc(s.input_audit?.start||daily[0]?.signal_date||'—')} → ${esc(s.requested_signal_date)} · 最多 ${esc(p.top_k)} 只 · 单边成本 ${esc(p.fee_bps??s.fee_bps??10)} bps</span></div>
${s.unliquidated?.length?`<p class="notice error">期末有 ${s.unliquidated.length} 只股票缺少可成交收盘价，已明确保留残仓，未伪造强平成交。</p>`:''}<div class="kpi-grid">${rows.map(r=>metricCard(r.factor+' · 账户累计收益',pct(r.total_return),'最大回撤 '+pct(r.max_drawdown),'cyan')+metricCard('已结束交易',r.trades??r.trade_count??0,'胜率 '+pct(r.win_rate),'')).join('')}</div>
<div class="visual-grid spaced"><div><h3>组合累计收益</h3>${interactiveFactorChart(daily,[['cum_return','累计收益','var(--cyan)'],['cum_excess','相对沪深300','var(--amber)']],true)}</div><div><h3>每日回撤与实际资金敞口</h3>${interactiveFactorChart(daily,[['drawdown','回撤','var(--red)'],['exposure','资金敞口','var(--green)']],true)}</div></div>
<div class="table-wrap spaced"><table><thead><tr><th>交易日</th><th>市场阶段</th><th>持仓数</th><th>资金敞口</th><th>账户日收益</th><th>累计收益</th></tr></thead><tbody>${daily.slice(-20).map(r=>`<tr><td>${esc(r.signal_date)}</td><td>${esc(({1:'上涨',0:'震荡','-1':'下跌'})[r.chan_phase]??'—')}</td><td>${num(r.n_held,0)}</td><td>${pct(r.exposure)}</td><td>${pct(r.port_ret)}</td><td>${pct(r.cum_return)}</td></tr>`).join('')}</tbody></table></div>
<p class="muted">${esc(s.strategy)}。收盘决策、次日开盘执行；每笔新买目标为当时净资产的 1/TopK，现金不足时同批等额分配；旧仓不每日再平衡。期末按收盘结算，收益来自现金和实际持仓。${esc((s.limitations||[]).join('；'))}</p>`}
function legacyFactorResult(s){const rows=s.metrics||s.factor_performance||[];const daily=s.daily_metrics||[];const winRows=daily.filter(r=>Number(r.in_window)===1);const p=s.effective_parameters||{};return `<div class="panel-head"><span class="pill ok">${s.signals_evaluated??winRows.length} 个成熟信号日（图含全量 ${daily.length} 日）</span>${s.kronos_source==='intraday'?'<span class="pill">分时 Kronos · 15:00→次日10:00</span>':s.kronos_source==='composite'?'<span class="pill">组合因子 · E1+E3+E5+E10</span>':'<span class="pill">日线 Kronos · rp10</span>'}${s.gate_applied?`<span class="pill">${s.gate_source==='chan'?'缠论门控·上涨段':'浪型门控 α='+esc(s.gate_alpha)}</span>`:''}<span class="muted">截至 ${esc(s.requested_signal_date||s.data_last_date||'—')} · Top ${esc(p.top_k??5)} · 卖出阈值 ${esc(s.exit_rank??1000)} · 每日收盘后自动刷新</span></div><div class="grid grid-3 spaced">${rows.map(r=>`<div class="metric"><label>${esc(r.factor)} · 平均 RankIC</label><strong class="${Number(r.mean_rank_ic)>=0?'red':'green'}">${num(r.mean_rank_ic)}</strong><div class="metric-secondary">策略胜率 <b class="${Number(r.win_rate)>=0.5?'red':'green'}">${r.win_rate!=null?pct(r.win_rate):'—'}</b> · 每笔均值 <b class="${Number(r.mean_return)>=0?'red':'green'}">${r.mean_return!=null?pct(r.mean_return):'—'}</b></div><small>${r.trades??0} 笔交易 · 相对沪深300超额 <b class="${Number(r.mean_excess)>=0?'red':'green'}">${r.mean_excess!=null?pct(r.mean_excess):'—'}</b> · ${r.ema!=null?'EMA '+esc(r.ema):'加权组合'}</small></div>`).join('')}</div><div class="spaced"><h3>每日 RankIC 对比</h3>${interactiveFactorChart(daily,[['kronos_ic','Kronos','var(--cyan)'],['set10_ic','SET10','var(--amber)'],['composite_ic','组合','var(--green)']],false)}</div><div class="visual-grid spaced"><div><h3>策略每日收益 vs 沪深300（每日复盘）</h3>${interactiveFactorChart(daily,[['port_ret','策略','var(--cyan)'],['bench_ret','沪深300','#94a3b8']],true)}</div><div><h3>浪型门控值（EMA 门控与当日敞口）</h3><div class="ifc-controls"><label class="muted">门控 EMA α <select class="gate-alpha">${[0.6,0.65,0.7,0.75,0.8,0.85,0.9].map(v=>`<option value="${v}" ${Number(state.gateAlpha||0.65)===v?'selected':''}>${v}</option>`).join('')}</select></label><span class="muted">EMA门控值 ≥0 为推动（当日敞口 1），&lt;0 为调整（空仓）</span></div><div id="gate-chart">${empty('等待浪型数据','加载大盘浪型后自动计算')}</div></div></div>${daily.length?`<div class="table-wrap spaced"><table><thead><tr><th>信号日</th><th>Kronos IC</th><th>SET10 IC</th><th>组合 IC</th><th>卖出交易</th><th>策略当日</th><th>累计超额</th></tr></thead><tbody>${winRows.map(r=>`<tr><td>${esc(r.signal_date)}</td><td>${num(r.kronos_ic)}</td><td>${num(r.set10_ic)}</td><td>${num(r.composite_ic)}</td><td>${esc(r.comp_day_trades??'—')} 笔</td><td class="${Number(r.port_ret)>=0?'red':'green'}">${r.port_ret!=null?pct(r.port_ret):'—'}</td><td class="${Number(r.cum_excess)>=0?'red':'green'}">${r.cum_excess!=null?pct(r.cum_excess):'—'}</td></tr>`).join('')}</tbody></table></div>`:''}<p class="muted">收益为历史前瞻评估，未扣交易费用；多个信号日持有区间可能重叠，不是组合净值。信号先排序，再统计可观测收益。${s.kronos_source==='intraday'?`口径：信号日 15:00 收盘 → 次日 10:00 收盘；分时分数 live ${esc((s.intraday_score_days?.live||[]).length)} 日 + OOS ${esc((s.intraday_score_days?.oos||[]).length)} 日。`:'口径：信号次日开盘进入，持有期末开盘计算。'}参数：Kronos ${esc(p.kronos_weight)} / SET10 ${esc(p.set10_weight)}，EMA ${esc(p.kronos_ema)} / ${esc(p.set10_ema)}。策略：信号日收盘等权买入 top-K，信号跌出前 ${esc(s.exit_rank??1000)} 名当日收盘卖出，数据末端强制清仓；超额相对沪深300；交易区间可重叠，非组合净值；策略日收益按持仓盯市，空仓日记 0；浪型门控启用时调整浪整体空仓。</p>`}
let _ifchartSeq=0;const IFC={};const IFG={W:1000,H:400,L:78,R:24,T:26,B:44};
function niceTicks(lo,hi,n){const span=hi-lo||1;const raw=span/n;const mag=Math.pow(10,Math.floor(Math.log10(raw)));const norm=raw/mag;const step=(norm<1.5?1:norm<3?2:norm<7?5:10)*mag;const start=Math.ceil(lo/step)*step;const out=[];for(let v=start;v<=hi+1e-9;v+=step)out.push(Number(v.toFixed(6)));return out}
function ifcSlice(st){const n=st.rows.length;const win=Math.min(st.win,n);const start=Math.max(0,Math.min(st.start,n-win));return {rows:st.rows.slice(start,start+win),offset:start,n:win,all:n}}
function ifcGeom(rows){const vals=rows.flatMap(r=>IFC._cur.series.map(([k])=>r[k])).filter(v=>v!=null&&Number.isFinite(Number(v))).map(Number);let lo=0,hi=1;if(vals.length){lo=Math.min(0,...vals);hi=Math.max(0,...vals)}const span=hi-lo||1;lo-=span*.06;hi+=span*.08;const n=rows.length;return {lo,hi,n,xf:i=>IFG.L+i*(IFG.W-IFG.L-IFG.R)/Math.max(n-1,1),yf:v=>IFG.T+(IFG.H-IFG.T-IFG.B)*(1-(Number(v)-lo)/(hi-lo))}}
function ifcRender(box){const st=IFC[box.dataset.ifchart];if(!st)return;IFC._cur=st;const sl=ifcSlice(st);const g=ifcGeom(sl.rows);const svg=box.querySelector('svg');const {W,H,L,R,T,B}=IFG;
const grid=niceTicks(g.lo,g.hi,4).map(v=>`<path d="M${L} ${g.yf(v).toFixed(1)}H${W-R}" class="gridline"/><text x="${L-8}" y="${(g.yf(v)+4).toFixed(1)}" text-anchor="end">${st.percent?pct(v):num(v,2)}</text>`).join('');
const nt=g.n,nx=Math.min(6,nt);let xt='';for(let k=0;k<nx;k++){const i=Math.round(k*(nt-1)/Math.max(nx-1,1));xt+=`<text x="${g.xf(i).toFixed(1)}" y="${H-12}" text-anchor="${k===0?'start':k===nx-1?'end':'middle'}">${esc(sl.rows[i]?.signal_date||'')}</text>`}
const paths=st.series.map(([key,,color],si)=>{let d='',prev=false;sl.rows.forEach((r,i)=>{const good=r[key]!=null&&Number.isFinite(Number(r[key]));if(good)d+=(prev?' L':'M')+g.xf(i).toFixed(1)+','+g.yf(r[key]).toFixed(1);prev=good});return `<path class="ifc-line" data-si="${si}" d="${d}" fill="none" stroke="${color}" stroke-width="2.2"/>`}).join('');
const dots=st.series.map(([, ,color],si)=>`<circle class="ifc-dot" data-si="${si}" r="4.5" fill="${color}" stroke="#0d1526" stroke-width="1.5" style="display:none"/>`).join('');
svg.innerHTML=`${grid}<path d="M${L} ${g.yf(0).toFixed(1)}H${W-R}" class="zero-line"/>${st.ref!=null?`<path d="M${L} ${g.yf(st.ref).toFixed(1)}H${W-R}" class="zero-line"/>`:''}${paths}<line class="ifc-cross" y1="${T}" y2="${H-B}" stroke="#7dd3fc" stroke-dasharray="4 4" stroke-width="1" style="display:none"/><g>${dots}</g><rect class="ifchart-hit" x="${L}" y="${T}" width="${W-L-R}" height="${H-T-B}" fill="transparent"/>${xt}`;
const rng=box.querySelector('.ifc-slider');if(rng){rng.max=Math.max(st.rows.length-st.win,0);rng.value=st.start;rng.disabled=st.rows.length<=st.win}
const info=box.querySelector('.ifc-range-info');if(info)info.textContent=`${sl.rows[0]?.signal_date||''} → ${sl.rows.at(-1)?.signal_date||''}（${sl.n}/${sl.all} 日）`}
function interactiveFactorChart(rows,series,percent,ref){if(!rows.length)return empty('暂无逐日数据','等待本次评估完成');const vals=rows.flatMap(r=>series.map(([k])=>r[k])).filter(v=>v!=null&&Number.isFinite(Number(v))).map(Number);if(!vals.length)return empty('暂无逐日数据','等待本次评估完成');const id='ifc'+(++_ifchartSeq);const win=rows.length>30?30:rows.length;IFC[id]={rows,series,percent,ref:ref==null?null:ref,win,start:Math.max(rows.length-win,0)};
return `<div class="ifchart" data-ifchart="${id}"><div class="chart-legend ifc-legend">${series.map(([k,l,c],si)=>`<span class="ifc-lg" data-si="${si}" style="color:${c};cursor:pointer">● ${l}</span>`).join('')}<span class="muted ifc-range-info" style="margin-left:auto"></span></div><svg viewBox="0 0 ${IFG.W} ${IFG.H}" class="stock-chart" role="img" aria-label="交互图表"></svg><div class="ifc-controls"><label class="muted">窗口 <input class="ifc-win" type="number" min="1" max="9999" step="10" value="${Math.min(30, rows.length)}"></label><input class="ifc-slider" type="range" min="0" max="0" value="0" style="flex:1"><span class="muted">← 平移</span></div><div class="ifchart-tip" style="display:none"></div>`.replace('?xml version','')}
(function(){document.addEventListener('mousemove',e=>{const hit=e.target.closest?e.target.closest('.ifchart-hit'):null;if(!hit)return;const box=hit.closest('.ifchart');if(!box)return;const st=IFC[box.dataset.ifchart];if(!st)return;IFC._cur=st;const b=hit.getBoundingClientRect();const rel=(e.clientX-b.left)/Math.max(b.width,1);const g=ifcGeom(ifcSlice(st).rows);let i=Math.round((IFG.L+rel*(IFG.W-IFG.L-IFG.R)-IFG.L)/((IFG.W-IFG.L-IFG.R)/Math.max(g.n-1,1)));i=Math.max(0,Math.min(g.n-1,i));const cross=box.querySelector('.ifc-cross');cross.style.display='';cross.setAttribute('x1',g.xf(i).toFixed(1));cross.setAttribute('x2',g.xf(i).toFixed(1));const dots=box.querySelectorAll('.ifc-dot');const rows=ifcSlice(st).rows;let tipHtml='<b>'+esc(rows[i]?.signal_date||'')+'</b>';st.series.forEach(([k,l,c],si)=>{const dot=dots[si];const v=rows[i]?.[k];const good=v!=null&&Number.isFinite(Number(v));if(good){dot.style.display='';dot.setAttribute('cx',g.xf(i).toFixed(1));dot.setAttribute('cy',g.yf(v).toFixed(1));tipHtml+='<br><span style="color:'+c+'">● '+esc(l)+'</span> <b>'+(st.percent?pct(v):num(v,3))+'</b>'}else dot.style.display='none'});
const tip=box.querySelector('.ifchart-tip');tip.innerHTML=tipHtml;tip.style.display='block';const bx=box.getBoundingClientRect();tip.style.left=Math.min(e.clientX-bx.left+14,Math.max(bx.width-tip.offsetWidth-8,8))+'px';tip.style.top=Math.max(0,e.clientY-bx.top-tip.offsetHeight-12)+'px'});document.addEventListener('mouseout',e=>{const hit=e.target.closest?e.target.closest('.ifchart-hit'):null;if(!hit)return;const box=hit.closest('.ifchart');if(!box)return;box.querySelectorAll('.ifc-cross,.ifc-dot').forEach(el=>el.style.display='none');const tip=box.querySelector('.ifchart-tip');if(tip)tip.style.display='none'});document.addEventListener('click',e=>{const lg=e.target.closest?e.target.closest('.ifc-lg'):null;if(!lg)return;const box=lg.closest('.ifchart');if(!box)return;const line=box.querySelector('.ifc-line[data-si="'+lg.dataset.si+'"]');const off=line.style.display==='none';line.style.display=off?'':'none';lg.style.opacity=off?'1':'.35'});document.addEventListener('input',e=>{const rng=e.target.closest?e.target.closest('.ifc-slider'):null;if(!rng)return;const box=rng.closest('.ifchart');if(!box)return;const st=IFC[box.dataset.ifchart];if(!st)return;st.start=Number(rng.value);ifcRender(box)});document.addEventListener('change',e=>{const sel=e.target.closest?e.target.closest('.ifc-win'):null;if(!sel)return;const box=sel.closest('.ifchart');if(!box)return;const st=IFC[box.dataset.ifchart];if(!st)return;const n=st.rows.length;st.win=Math.max(1,Math.min(Number(sel.value)||n,n));st.start=Math.max(n-st.win,0);ifcRender(box)})})();
function factorLineChart(rows,series,percent){const vals=rows.flatMap(r=>series.map(([k])=>r[k])).filter(v=>v!=null&&v!==''&&Number.isFinite(Number(v))).map(Number);if(!vals.length)return empty('暂无逐日数据','等待本次评估完成');const lo=Math.min(0,...vals),hi=Math.max(0,...vals),span=hi-lo||1;const x=i=>48+i*540/Math.max(rows.length-1,1),y=v=>178-(Number(v)-lo)*145/span;const paths=series.map(([key,label,color])=>{let d='',prev=false;rows.forEach((r,i)=>{const good=r[key]!=null&&r[key]!==''&&Number.isFinite(Number(r[key]));if(good)d+=(prev?' L':' M')+x(i)+','+y(r[key]);prev=good});return `<path d="${d}" fill="none" stroke="${color}" stroke-width="2"/>`}).join('');const dots=series.map(([key,label])=>rows.map((r,i)=>{const good=r[key]!=null&&r[key]!==''&&Number.isFinite(Number(r[key]));return good?`<circle cx="${x(i).toFixed(1)}" cy="${y(r[key]).toFixed(1)}" r="7" fill="transparent" class="hover-dot" data-tip="${esc(label)} · ${esc(r.signal_date||'')} · ${percent?pct(r[key]):num(r[key],3)}"/>`:''}).join('')).join('');return `<div class="chart-legend">${series.map(([,l,c])=>`<span style="color:${c}">● ${l}</span>`).join('')}</div><svg viewBox="0 0 620 220" class="stock-chart" role="img" aria-label="逐日因子表现"><path d="M48 33H590M48 105H590M48 178H590" class="gridline"/><path d="M48 ${y(0)}H590" class="zero-line"/>${paths}<text x="2" y="36">${percent?pct(hi):num(hi,2)}</text><text x="2" y="180">${percent?pct(lo):num(lo,2)}</text><text x="48" y="208">${esc(rows[0]?.signal_date)}</text><text x="505" y="208">${esc(rows.at(-1)?.signal_date)}</text>${dots}</svg>`}
const kindNames={trend_refresh:'趋势数据刷新',data_update:'数据更新',factor_evaluate:'因子评估',composite_factor:'组合因子',intraday_predict:'分时动态预测',predict:'Kronos 推演'};
const statusNames={queued:'排队中',running:'运行中',completed:'已完成',failed:'失败',error:'错误'};
function jobProgress(r){const done=['completed','failed','error'].includes(r.status);const deferred=Boolean(r.deferred)||String(r.stage||'').includes('等待官方日线');const partial=String(r.stage||'').includes('partial')||r.partial||r.intraday_status==='partial'||r.intraday_partial;const label=deferred?'等待官方日线':(partial?'分时部分更新':(statusNames[r.status]||r.status));const live=r.live_predictions;const liveBlock=live&&live.top?.length?`<div class="live-box"><p class="muted">实时预览：已计算 <b class="cyan">${live.count??live.top.length}</b>${live.total?` / ${live.total}`:''} 只 · 分片仍在进行，排名未最终确定</p><div class="table-wrap"><table><thead><tr><th>代码</th><th>预测收益</th></tr></thead><tbody>${live.top.map(x=>`<tr><td>${esc(x.ts_code)}</td><td class="${x.pred_return>=0?'red':'green'}">${(x.pred_return*100).toFixed(2)}%</td></tr>`).join('')}</tbody></table></div></div>`:'';return `<div class="job-status"><b>${esc(kindNames[r.kind]||r.kind||'任务')}</b><span class="pill ${deferred||partial?'warn':r.status==='completed'?'ok':r.status==='failed'||r.status==='error'?'bad':''}">${esc(label)}</span><span class="muted">${esc(r.id||'')}</span></div>${!done?'<div class="progress"><i></i></div>':''}<p class="muted">${esc(r.error||r.stage||(deferred?'官方日线尚未发布，已保留上一份完整面板，稍后可重试':(partial?`分时结果为部分更新，失败 ${r.intraday_failure_count??'部分'} 只；建议稍后重试。`:(r.kind==='data_update'&&!done?'正在逐股票检查分时数据；以下为服务器最近确认的进度，刷新页面可恢复查看。':(done?'执行结束':'正在读取数据并计算，请稍候')))))}</p>${liveBlock}<pre class="log-tail">${esc((r.tail||[]).slice(-60).join('\n')||'等待任务日志…')}</pre>`}
function updateRunOutput(el,html){if(!el)return;const prev=el.querySelector('.log-tail');const pinned=!prev||prev.scrollTop+prev.clientHeight>=prev.scrollHeight-30;const prevTop=prev?prev.scrollTop:0;el.innerHTML=html;const pre=el.querySelector('.log-tail');if(pre){if(pinned){pre.scrollTop=pre.scrollHeight}else{pre.scrollTop=Math.min(prevTop,Math.max(0,pre.scrollHeight-pre.clientHeight))}}}
function replaceRun(run){const i=state.runs.findIndex(x=>x.id===run.id);if(i<0)state.runs.unshift(run);else state.runs[i]=run}
function dataRunOutput(run,extra=''){const el=document.querySelector('#data-run-output');if(!el||state.page!=='data')return;if(extra){updateRunOutput(el,`<p class="notice warn">${esc(extra)}</p>`+jobProgress(run));return}updateRunOutput(el,jobProgress(run))}
const dataWatchers={};
async function watchDataJob(job){
  if(!job)return;
  syncDataControls();
  if(dataWatchers[job.id])return dataWatchers[job.id];
  const promise=(async()=>{let run=job,delay=2500,lastConfirmed=Date.now();
    try{
      dataRunOutput(run);
      while(['queued','running'].includes(run.status)){
        await new Promise(r=>setTimeout(r,delay));
        try{run=await api('/runs/'+encodeURIComponent(job.id),{timeout:20000});lastConfirmed=Date.now();replaceRun(run);delay=2500;dataRunOutput(run);syncDataControls()}
        catch(err){delay=Math.min(30000,Math.round(delay*1.7));dataRunOutput(run,`暂时无法读取服务器状态（${err.message}）。上次确认于 ${fmtTime(lastConfirmed)}：${statusNames[run.status]||run.status}；当前状态未知，${Math.round(delay/1000)} 秒后自动重试。`)}
      }
      replaceRun(run);
      let statusError='';
      try{state.status=await api('/status');updateTop()}catch(e){statusError='任务已结束，但读取最新数据状态失败；上方保留上次确认值，可点击右上角刷新。'}
      refreshDataView();
      dataRunOutput(run,statusError||(['failed','error'].includes(run.status)?run.error||'更新任务失败，请查看日志末尾':''));
      return run;
    }finally{delete dataWatchers[job.id];syncDataControls()}
  })();
  dataWatchers[job.id]=promise;return promise;
}
async function startDataJob(params){if(!can('data_update'))return;const active=activeDataRun();if(active){toast('已有数据更新任务，已接续读取服务器进度');return watchDataJob(active)}if(state.busy){toast('已有任务正在执行，请等待完成');return}state.busy=true;setBusy(true);try{const job=await api('/jobs',{method:'POST',body:JSON.stringify({kind:'data_update',params}),timeout:30000});replaceRun(job);toast(job.reused?'已接续服务器上的数据更新任务':'数据更新已启动：'+job.id);await watchDataJob(job)}catch(e){toast(e.message,'error');dataRunOutput({status:'error',error:e.message})}finally{state.busy=false;setBusy(false)}}
async function startJob(kind,params,selector){if(kind==='data_update')return startDataJob(params);if(!can(kind))return;if(state.busy){toast('已有任务正在执行，请等待完成');return}const page=state.page;const target=()=>state.page===page?document.querySelector(selector):null;state.busy=true;setBusy(true);try{const job=await api('/jobs',{method:'POST',body:JSON.stringify({kind,params}),timeout:30000});replaceRun(job);toast('任务已启动：'+job.id);let run=job,pollErrors=0;while(true){const el=target();if(el){el.classList.remove('empty-state');updateRunOutput(el,jobProgress(run))}if(['completed','failed','error'].includes(run.status))break;await new Promise(resolve=>setTimeout(resolve,2500));try{run=await api('/runs/'+encodeURIComponent(job.id),{timeout:20000});pollErrors=0}catch(err){pollErrors++;if(pollErrors>=12)throw Error('暂时无法读取任务状态；任务仍在服务器运行，请刷新页面恢复查看。');continue}}state.runs=listPayload(await api('/runs'),'runs');if(run.status!=='completed')throw Error(run.error||'执行失败，请查看日志末尾');if(kind==='factor_evaluate'){state.factorLatest=await api('/factors/latest');if(target())resultInto(target(),run.result?run:state.factorLatest)}else if(kind==='composite_factor'){state.compositeLatest=await api('/composite/latest');if(target())resultInto(target(),run.result?run:state.compositeLatest)}else if(kind==='intraday_predict'){state.intradayLatest=await api('/intraday/latest');if(target())resultInto(target(),state.intradayLatest);loadIntradayAnalytics()}else if(kind==='predict'){state.latest=await api('/results/latest');if(state.page===page)renderPage(false)}else if(kind==='chan_multi'){await loadChanMulti()}else{state.status=await api('/status');updateTop()}toast((run.deferred?'官方日线尚未就绪，请稍后重试：':'任务已完成：')+job.id)}catch(e){toast(e.message,'error');const el=target();if(el)el.insertAdjacentHTML('afterbegin','<p class="notice error">'+esc(e.message)+'</p>')}finally{state.busy=false;setBusy(false)}}
function setBusy(on){for(const id of ['start-data','validate-data','run-factors','run-composite','start-predict','run-intraday','run-chan-multi']){const el=document.querySelector('#'+id);if(el)el.disabled=on}}
async function resumeDataJob(job){return watchDataJob(job)}
function championCell(v){return v==null||v===''?'—':esc(typeof v==='number'?Number(v).toLocaleString('zh-CN',{maximumFractionDigits:4}):v)}
function championTable(rows,cols){if(!rows?.length)return empty('暂无工作簿数据');return `<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,200).map(r=>`<tr ${r['股票代码']?`data-champion-code=\"${esc(r['股票代码'])}\"`:''}>${cols.map(c=>`<td>${championCell(r[c])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><small class="muted">显示前 ${Math.min(200,rows.length)} 行，共 ${rows.length} 行</small>`}
function championResult(d){const sh=d.sheets||{},r=sh['每日记录']?.rows?.[0]||{};const inds=sh['行业最新']?.rows||[],curve=sh['E市场曲线']?.rows||[],checks=sh['检查审计']?.rows||[];const indCols=['行业排名','申万二级','股票数','合格股数','行业EMA中位数','行业EMA均值','正分宽度','首选代码'];const curveCols=['E期限','目标日','有效股票','平均统一Z','中位统一Z','截面标准差','正Z占比'];const checkCols=['检查项','观测值','期望','状态'];return `<div class="kpi-grid compact">${metricCard('报告目标日',r['目标日'],'信号日 '+(r['信号日']||'—'),'cyan')}${metricCard('有效个股分数',r['有效个股分数'],'可排名合格股 '+(r['可排名合格股']||'—'))}${metricCard('模型',r['模型短名'],'EMA '+(r['EMA decay']??.88)+' · '+(r['平滑交易日数']??10)+' 日')}${metricCard('申万二级行业',r['申万二级行业']??inds.length,checks.length+' 项审计记录')}</div><details open><summary>股票排名 · 全量搜索与分页</summary><div class="stock-query"><input id="champion-search" placeholder="搜索代码、股票名称或行业" aria-label="搜索冠军模型股票"><button class="btn ghost" id="champion-prev">上一页</button><button class="btn ghost" id="champion-next">下一页</button><span id="champion-page" class="muted"></span></div><div id="champion-stocks"></div><div id="champion-stock-detail" class="notice">点击股票行查看 E1–E10 原始分数与筛选字段</div></details><details><summary>行业最新排名（${inds.length} 个）</summary>${championTable(inds,indCols)}</details><details><summary>E1–E10 市场曲线</summary>${factorLineChart(curve.map(r=>({signal_date:r['E期限'],mean:r['平均统一Z'],median:r['中位统一Z'],p10:r['P10'],p90:r['P90']})),[['mean','平均 Z','var(--cyan)'],['median','中位 Z','var(--green)'],['p10','P10','var(--amber)'],['p90','P90','var(--red)']],false)}${championTable(curve,curveCols)}</details><details><summary>模型参数</summary>${championTable(sh['参数']?.rows||[],['类别','参数','当前值','单位','说明'])}</details><details><summary>检查审计</summary>${championTable(checks,checkCols)}</details><p class="muted">原始工作簿：Kronos_20260903_冠军模型_10日EMA088_市场相对预测.xlsx。EMA、统一 Z 和相对标签沿用原表口径。</p>`}
async function loadChampion(){const el=document.querySelector('#champion-workbook');if(!el||el.dataset.loaded)return;try{const d=await api('/champion_workbook');if(!d.available)throw Error(d.reason||'工作簿摘要不可用');el.classList.remove('empty-state');el.innerHTML=championResult(d);el.dataset.loaded='1';let page=0;const rows=d.sheets?.['个股最新']?.rows||[],cols=['股票代码','股票名称','申万二级','正式收盘','全市场排名','合格股排名','10日EMA分数','EMA百分位','市场相对标签'];function show(){const q=el.querySelector('#champion-search').value.trim().toLowerCase();const filtered=rows.filter(r=>!q||[r['股票代码'],r['股票名称'],r['申万一级'],r['申万二级']].join(' ').toLowerCase().includes(q));const total=Math.max(1,Math.ceil(filtered.length/50));page=Math.max(0,Math.min(page,total-1));el.querySelector('#champion-stocks').innerHTML=championTable(filtered.slice(page*50,page*50+50),cols);el.querySelectorAll('[data-champion-code]').forEach(tr=>tr.addEventListener('click',()=>{const r=rows.find(x=>x['股票代码']===tr.dataset.championCode)||{};const keys=['E1统一Z','E2统一Z','E3统一Z','E4统一Z','E5统一Z','E6统一Z','E7统一Z','E8统一Z','E9统一Z','E10统一Z'];el.querySelector('#champion-stock-detail').innerHTML='<b>'+championCell(r['股票名称'])+' · '+championCell(r['股票代码'])+'</b>　EMA '+championCell(r['10日EMA分数'])+'　标签 '+championCell(r['市场相对标签'])+'<br>'+keys.map(k=>k+' '+championCell(r[k])).join('　');}));el.querySelector('#champion-page').textContent=`第 ${page+1} / ${total} 页 · ${filtered.length} 只`;el.querySelector('#champion-prev').disabled=page===0;el.querySelector('#champion-next').disabled=page>=total-1}el.querySelector('#champion-search').addEventListener('input',()=>{page=0;show()});el.querySelector('#champion-prev').addEventListener('click',()=>{page--;show()});el.querySelector('#champion-next').addEventListener('click',()=>{page++;show()});show()}catch(e){el.innerHTML='<div class="notice error">冠军模型工作簿读取失败：'+esc(e.message)+'</div>'}}
function factorStockCard(d){const o=(d?.ohlc||[]).slice(-5),h=d?.horizon||[];if(!o.length)return '<span class="muted">暂无5日K线</span>';const closes=o.map(x=>Number(x.close)).filter(Number.isFinite);const lo=Math.min(...closes),hi=Math.max(...closes),span=hi-lo||1;const bars=o.map((x,i)=>{const x0=12+i*34,y=70-(Number(x.close)-lo)*48/span,hy=70-(Number(x.high)-lo)*48/span,ly=70-(Number(x.low)-lo)*48/span,oy=70-(Number(x.open)-lo)*48/span;const up=Number(x.close)>=Number(x.open);return `<path d="M${x0+7},${hy}V${ly}" class="wick"/><rect x="${x0}" y="${Math.min(y,oy)}" width="14" height="${Math.max(2,Math.abs(y-oy))}" class="candle ${up?'up':'down'}"/>`}).join('');const base=Number(o.at(-1).close);const fc=h.slice(0,2).map((x,i)=>base*(1+Number(x.raw_mean||0)));const vals=[base,...fc].filter(Number.isFinite);const flo=Math.min(...vals),fhi=Math.max(...vals),fsp=fhi-flo||1;const line=vals.map((v,i)=>`${i?'L':'M'}${190+i*54},${70-(v-flo)*48/fsp}`).join(' ');return `<div class="stock-context"><div class="chart-label">过去5日K线 <span>→</span> 预测2日收盘路径</div><svg viewBox="0 0 310 82" class="mini-kline" role="img" aria-label="过去5日K线和预测2日收盘路径">${bars}<path d="${line}" class="forecast-line"/><line x1="180" y1="8" x2="180" y2="76" class="forecast-divider"/></svg><small class="muted">历史截至 ${esc(o.at(-1).timestamps?.slice(0,10)||'—')} · 预测为模型收盘估计，不构造虚假 OHLC</small></div>`}
function compositeResult(s){const top=s?.top||[];return `<div class="kpi-grid compact">${metricCard('组合因子',s?.factor_group||'—','E1–E10 横截面组合','cyan')}${metricCard('信号日',s?.signal_date||'—','组合分数最新信号日','green')}${(s?.future||[]).map(f=>metricCard('E'+f.horizon+' 预测→'+f.target_date,f.topk_mean_raw!=null?num(f.topk_mean_raw):'—','TopK 原始预测均值','cyan')).join('')}${metricCard('覆盖股票',s?.universe??'—','有有效因子分数')}${metricCard('稳定候选',s?.stable_count??0,'近期持续进入 TopK','green')}${metricCard('破位提醒',s?.break_count??0,'需要复核/退出','amber')}</div><p class="muted">${esc((s?.horizons||[]).map(x=>'E'+x).join(' + '))} · 权重 ${esc((s?.weights||[]).map(x=>Number(x).toFixed(2)).join(' / ')||'等权')}。稳定性来自最近 ${esc(s?.lookback_days??5)} 个信号日的持续排名，不使用未来收益。</p></p><div class="spaced"><h3>组合 TopK 次日预测均值（E1 原始值，按信号日）</h3>${interactiveFactorChart((s?.date_summary||[]).map(r=>({signal_date:r.date,pred:r.pred_e1_mean})),[['pred','TopK 次日预测均值(E1)','var(--cyan)']],true)}</div>${top.length?`<div class="table-wrap"><table><thead><tr><th>代码</th><th>名称</th><th>行业/类别</th><th>组合分数</th>${(s?.horizons||[]).map(h=>`<th>E${h} 预测</th>`).join('')}<th>排名</th><th>稳定性</th><th>5日K/2日预测</th></tr></thead><tbody>${top.slice(0,20).map(r=>`<tr><td><button class="factor-stock-link" data-factor-stock="${esc(r.ts_code)}">${esc(r.ts_code)}</button></td><td>${esc(r.name||'—')}</td><td>${esc(r.industry||r.market||'—')}</td><td>${num(r.composite_score)}</td>${(s?.horizons||[]).map(h=>`<td>${num(r['pred_e'+h])}</td>`).join('')}<td>${esc(r.rank??'—')}</td><td><span class="pill ${r.stability_status==='stable'?'ok':r.stability_status==='break'?'bad':''}">${esc(r.stability_status||'watch')}</span></td><td><div class="factor-stock-context" id="factor-stock-${esc(r.ts_code).replace(/[^A-Za-z0-9_-]/g,'_')}"><button class="btn ghost factor-load-stock" data-factor-stock="${esc(r.ts_code)}">查看K线</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('暂无组合排名','请运行组合因子')}</div>`}

function bindFactorStockInteractions(){document.querySelectorAll("[data-factor-stock]").forEach(e=>{if(e.dataset.bound)return;e.dataset.bound="1";e.addEventListener("click",async()=>{const code=e.dataset.factorStock;const id="factor-stock-"+code.replace(/[^A-Za-z0-9_-]/g,"_");const box=document.querySelector("#"+id);if(!box)return;box.innerHTML="读取真实K线…";try{const d=await api("/market_snapshot?mode=stock&symbol="+encodeURIComponent(code)+"&limit=90",{timeout:90000});box.innerHTML=factorStockCard(d)}catch(err){const m=String(err.message||err);box.innerHTML='<span class="notice error">K线读取失败：'+esc(m.includes("aborted")?"读取超时（首次加载行情面板较慢），请再点一次重试":m)+"</span>"}})})}
function intradayPayload(raw){return raw?.result?.result||raw?.result||raw||{}}
function intradayRows(s){const all=s?.predictions||s?.latest||[];return Array.isArray(all)?all:(all?.rows||[])}
function parsePath(r){let v=r?.pred_close_path??r?.prediction_path??r?.predicted_path??r?.path??r?.predicted_close; if(typeof v==='string'){try{v=JSON.parse(v)}catch{return []}} if(!Array.isArray(v))return [];return v.map(x=>typeof x==='object'?Number(x.close??x.value??x.pred_close):Number(x)).filter(Number.isFinite)}
function pathSpark(r){const a=parsePath(r);if(a.length<2)return '<span class="muted">无16bar路径</span>';const lo=Math.min(...a),hi=Math.max(...a),span=hi-lo||1,d=a.map((v,i)=>`${i?'L':'M'}${(i*108/(a.length-1)).toFixed(1)},${(39-(v-lo)*33/span).toFixed(1)}`).join(' ');return `<svg class="intraday-spark" viewBox="0 0 108 42" role="img" aria-label="模型预测路径"><path d="${d}"/></svg>`}
function intradayStockDetail(r){const path=parsePath(r);if(!path.length)return empty('暂无预测路径','该接口未提供 16 bar 预测序列');const lo=Math.min(...path),hi=Math.max(...path),last=Number(r.last_close);return `<div class="intraday-detail"><div><b>${esc(r.name||r.ts_code)}</b><span class="muted"> ${esc(r.ts_code)} · 预测路径（不是实际成交价）</span></div><svg class="intraday-path" viewBox="0 0 620 190" role="img" aria-label="16 bar Kronos 预测路径"><path d="M48 24H590M48 95H590M48 166H590" class="gridline"/><path d="${path.map((v,i)=>`${i?'L':'M'}${48+i*542/(path.length-1)},${166-(v-lo)*142/(hi-lo||1)}`).join(' ')}" class="forecast-line"/><text x="4" y="28">${num(hi,2)}</text><text x="4" y="170">${num(lo,2)}</text><text x="48" y="184">bar 1 · ${num(last,2)} 当前价</text><text x="500" y="184">bar ${path.length}</text></svg></div>`}
function intradayChangeTable(changes){if(!changes?.length)return empty('没有变化','首次运行会建立基线，下一次运行显示信号变化');return `<div class="table-wrap"><table><thead><tr><th>代码</th><th>变化</th><th>此前</th><th>现在</th></tr></thead><tbody>${changes.slice(0,50).map(x=>`<tr><td>${esc(x.ts_code||x.to?.ts_code)}</td><td>${esc(x.change||'—')}</td><td>${esc(x.from?.stability_status||'—')} ${x.from?.ema_signal!=null?num(x.from.ema_signal):''}</td><td>${esc(x.to?.stability_status||'—')} ${x.to?.ema_signal!=null?num(x.to.ema_signal):''}</td></tr>`).join('')}</tbody></table></div>`}
function intradayResult(raw){const s=intradayPayload(raw),rows=intradayRows(s),buys=s?.buy_candidates||[],pos=s?.positions||s?.paper_positions||[],changes=s?.changes||[];const merged=[...buys,...rows.filter(x=>!buys.some(b=>b.ts_code===x.ts_code))];return `<div class="kpi-grid compact">${metricCard('信号日',s?.signal_date||'—','最新可用分时数据','cyan')}${metricCard('尾盘买入候选',buys.length,'14:45–14:55 · T+1 可卖','green')}${metricCard('稳定验证',s?.stable_verified_count??rows.filter(x=>x.stability_status==='stable_verified').length,'只','green')}${metricCard('持仓提醒',pos.filter(x=>x.action&&x.action!=='HOLD').length,'需处理','amber')}</div><div class="notice">买入窗口：14:45–14:55 尾盘；卖出：T+1 后 EMA 信号转负、亏损达到 5% 止损、或最多持有 8 个 bar，先到先卖。模型路径用于研究和提醒，不保证最佳买卖点。</div><div class="intraday-meta"><span>最新 bar：${esc(s?.manifest?.observed_latest_bar||s?.observed_latest_bar||'—')}</span><span>生成：${esc(fmtTime(s?.generated_at||s?.manifest?.generated_at))}</span><span>数据状态：${esc(s?.manifest?.freshness||'current')}</span><span>记录变化：${changes.length} 条</span></div>${merged.length?`<details open><summary>预测股票与 16 bar 路径（${merged.length} 条）</summary><div class="table-wrap"><table class="intraday-table"><thead><tr><th>代码</th><th>预测收益</th><th title="跨信号日因果 EMA（α=0.25）：对每只股票按历史已发布预测递推叠加，而非当日单点">EMA(历史)</th><th title="历史 EMA 在全部股票中的截面分位">分位</th><th>状态</th><th>路径</th><th></th></tr></thead><tbody>${merged.slice(0,100).map((r,i)=>`<tr data-intraday-code="${esc(r.ts_code)}"><td><button class="intraday-stock-link" data-intraday-select="${esc(r.ts_code)}">${esc(r.name||r.ts_code)}</button><small>${esc(r.ts_code)}</small></td><td class="${Number(r.pred_return)>=0?'red':'green'}">${pct(r.pred_return)}</td><td title="${r.ema_days!=null?`基于 ${r.ema_days} 个信号日递推`:'仅当日'}">${num(r.ema_signal_hist??r.ema_signal,4)}</td><td>${pct(r.signal_rank_hist??r.signal_rank)}</td><td><span class="pill ${r.stability_status==='stable_verified'?'ok':r.stability_status==='breakdown'?'bad':''}">${esc(r.stability_status||r.buy_action||'watch')}</span></td><td>${pathSpark(r)}</td><td><button class="btn ghost intraday-use-stock" data-intraday-use="${esc(r.ts_code)}">录入持仓</button></td></tr>`).join('')}</tbody></table></div><div id="intraday-selected-detail" class="notice">点击股票代码查看模型 16 bar 路径</div></details>`:empty('暂无预测股票','模型尚未输出可展示的分时预测')}<details><summary>本次与上次预测的变化（${changes.length} 条）</summary>${intradayChangeTable(changes)}</details>${pos.length?`<details><summary>卖出提醒明细（${pos.length} 条 · 买卖操作在下方纸上账户）</summary><div class="table-wrap"><table><thead><tr><th>代码</th><th>股数</th><th>现价</th><th>收益</th><th>EMA 信号</th><th>动作</th></tr></thead><tbody>${pos.map(r=>`<tr class="${r.action&&r.action!=='HOLD'?'position-alert':''}"><td>${esc(r.ts_code)}</td><td>${esc(r.shares??'—')}</td><td>${num(r.last_price,2)}</td><td>${pct(r.return)}</td><td>${num(r.ema_signal)}</td><td><b>${esc(r.action||'HOLD')}</b></td></tr>`).join('')}</tbody></table></div></details>`:empty('暂无模拟持仓','在下方“纸上账户”录入，或从预测表点“录入持仓”')}<p class="muted">${(s?.warnings||[]).map(esc).join(' · ')}</p>`}
function intradayAnalyticsResult(raw){const s=raw?.result||raw||{};const industries=s.industry_rankings||s.industries||s.industry_rank||s.industry_ranking?.rows||[];const rows=Array.isArray(industries)?industries:[];const curve=s.market_curve_points||s.market_curve?.points||s.market_curves||s.curve||[];const points=Array.isArray(curve)?curve:[];const vals=points.map(x=>Number(x.value??x.close??x.return)).filter(Number.isFinite);const lo=Math.min(...vals,0),hi=Math.max(...vals,0),span=hi-lo||1;const path=vals.length>1?vals.map((v,i)=>`${i?'L':'M'}${48+i*542/(vals.length-1)},${166-(v-lo)*142/span}`).join(' '):'';const dots=points.map((p,i)=>{const v=Number(p.value??p.close??p.return);return Number.isFinite(v)?`<circle cx="${(48+i*542/Math.max(vals.length-1,1)).toFixed(1)}" cy="${(166-(v-lo)*142/span).toFixed(1)}" r="8" fill="transparent" class="hover-dot" data-tip="${esc(p.timestamp||p.time||'')} · ${num(v,4)}"/>`:''}).join('');const asof=s.asof||s.timestamp||s.source?.observed_latest_bar||'';const stockTotal=s.industry_ranking?.stock_count??'';return `<div class="intraday-analytics-grid"><div><div class="chart-title">行业 Top 10 概览 <span>${esc(asof)}</span></div>${rows.length?`<div class="industry-rank-list">${rows.slice(0,10).map((r,i)=>{const name=r.industry||r.name||r.category||'—';const ret=Number(r.pred_return??r.mean_pred_return??r.return??r.score);return `<div class="industry-rank-row"><b>${i+1}</b><span>${esc(name)}</span><i><em style="width:${Math.max(3,Math.min(100,Math.abs(ret||0)*300+10))}%"></em></i><strong class="${ret>=0?'red':'green'}">${Number.isFinite(ret)?pct(ret):num(ret)}</strong></div>`}).join('')}</div>`:empty('暂无行业排名','后端快照尚未生成')}</div><div><div class="chart-title">市场曲线 <span>${esc(s.market||'全市场')}</span></div>${vals.length>1?`<svg viewBox="0 0 620 210" class="stock-chart" role="img" aria-label="分时市场曲线"><path d="M48 33H590M48 105H590M48 178H590" class="gridline"/><path d="M48 ${166-(0-lo)*142/span}H590" class="zero-line"/><path d="${path}" class="forecast-line"/>${dots}<text x="4" y="36">${num(hi,3)}</text><text x="4" y="180">${num(lo,3)}</text><text x="48" y="202">${esc(points[0]?.timestamp||points[0]?.time||'')}</text><text x="500" y="202">${esc(points.at(-1)?.timestamp||points.at(-1)?.time||'')}</text></svg>`:empty('暂无市场曲线','后端快照尚未生成')}</div></div>${rows.length?`<div id="intraday-ic-overall">${renderIntradayIcOverall()}</div><details open class="intraday-industry-full"><summary>行业完整排名（${rows.length} 个行业${stockTotal?` · ${esc(stockTotal)} 只`:''} · 点击行查看成分股）</summary><div class="stock-query"><input id="intraday-industry-search" placeholder="搜索行业名称、股票代码或名称" aria-label="搜索分时行业排名"></div><div id="intraday-industry-table"></div></details>`:''}`}
function intradayIndustryPanel(){const box=document.querySelector('#intraday-industry-table');if(!box)return;const a=state.intradayAnalytics||{};const rows=a.industry_rankings||a.industry_ranking?.rows||[];const icMap={};(state.intradayIc?.available?state.intradayIc.industries:[]).forEach(x=>icMap[x.industry]=x);const expanded=new Set();const sort={key:null,dir:-1};const search=document.querySelector('#intraday-industry-search');const cols=[['rank','排名',r=>Number(r.rank)],['industry','行业',null],['stock_count','股票数',r=>Number(r.stock_count)],['mean_pred','平均预测',r=>r.mean_pred_return==null?null:Number(r.mean_pred_return)],['pos','正收益占比',r=>r.positive_ratio==null?null:Number(r.positive_ratio)],['ic','IC均值',r=>icMap[r.industry]?.mean_ic==null?null:Number(icMap[r.industry].mean_ic)],['trend','IC趋势',null],['dir','方向准确率',r=>icMap[r.industry]?.dir_acc==null?null:Number(icMap[r.industry].dir_acc)]];function chip(x){return `<span class="industry-stock-chip"><b>${esc(x.name||x.ts_code||'')}</b><small>${esc(x.ts_code||'')}</small><i class="${Number(x.pred_return)>=0?'red':'green'}">${pct(x.pred_return)}</i></span>`}function render(){const q=(search?.value||'').trim().toLowerCase();const filtered=rows.filter(r=>!q||[r.industry||'',...(r.top_stocks||[]).map(x=>`${x.ts_code||''}${x.name||''}`)].join(' ').toLowerCase().includes(q));let view=filtered.slice();if(sort.key){const get=cols.find(c=>c[0]===sort.key)?.[2];if(get)view.sort((p,q2)=>{const vp=get(p),vq=get(q2);if(vp==null&&vq==null)return 0;if(vp==null)return 1;if(vq==null)return -1;return (vp-vq)*sort.dir})}if(!view.length){box.innerHTML=empty('没有匹配的行业','换个关键词试试');return}const head=cols.map(c=>c[2]?`<th class="sortable" data-skey="${c[0]}" title="点击按${c[1]}排序">${c[1]}${sort.key===c[0]?(sort.dir<0?' ▼':' ▲'):''}</th>`:`<th>${c[1]}</th>`).join('')+'<th>首选股票</th>';box.innerHTML=`<div class="table-wrap"><table><thead><tr>${head}</tr></thead><tbody>${view.map(r=>{const name=r.industry||'—';const open=expanded.has(name);const top=(r.top_stocks||[])[0];const ic=icMap[name];const detail=(r.top_stocks||[]).map(chip).join('')||'<small class="muted">无成分股数据</small>';return `<tr class="industry-main ${open?'open':''}" data-industry="${esc(name)}"><td>${num(r.rank,0)}</td><td><i class="caret">${open?'▾':'▸'}</i>${esc(name)}</td><td>${num(r.stock_count,0)}</td><td class="${Number(r.mean_pred_return)>=0?'red':'green'}">${pct(r.mean_pred_return)}</td><td>${pct(r.positive_ratio)}</td><td class="${ic&&ic.mean_ic!=null?(ic.mean_ic>0?'red':'green'):''}">${ic&&ic.mean_ic!=null?num(ic.mean_ic,3):'—'}</td><td>${ic?miniTrend(ic.series):'<span class="muted">—</span>'}</td><td>${ic&&ic.dir_acc!=null?pct(ic.dir_acc):'—'}</td><td>${top?`${esc(top.name||top.ts_code||'')}<small>${esc(top.ts_code||'')}</small>`:'—'} ${top?`<b class="${Number(top.pred_return)>=0?'red':'green'}">${pct(top.pred_return)}</b>`:''}</td></tr><tr class="industry-detail" ${open?'':'style="display:none"'}><td colspan="9">${detail}</td></tr>`}).join('')}</tbody></table></div><small class="muted">共 ${view.length} 个行业 · 点列头按该列升/降序（再点一次反向）· IC=预测与实际收益的秩相关（窗口 ${state.intradayIc?.window_days??'—'} 日）· 点击行展开前 5 领涨股</small>`;box.querySelectorAll('th.sortable').forEach(th=>th.addEventListener('click',()=>{const k=th.dataset.skey;if(sort.key===k)sort.dir*=-1;else{sort.key=k;sort.dir=-1}render()}));box.querySelectorAll('tr.industry-main').forEach(tr=>tr.addEventListener('click',()=>{const name=tr.dataset.industry;const detail=tr.nextElementSibling;const open=expanded.has(name);if(open)expanded.delete(name);else expanded.add(name);detail.style.display=open?'none':'';tr.classList.toggle('open',!open);const caret=tr.querySelector('.caret');if(caret)caret.textContent=open?'▸':'▾'}))}
if(search)search.addEventListener('input',render);render()}
async function loadIntradayAnalytics(){const el=document.querySelector('#intraday-analytics');if(!el)return;try{const raw=await api('/intraday/analytics');state.intradayAnalytics=raw?.result||raw;el.innerHTML=raw?.available===false?empty('暂无分时快照',raw.reason||'行业排名与市场曲线尚未生成'):intradayAnalyticsResult(raw);intradayIndustryPanel();const asof=document.querySelector('#intraday-analytics-asof');if(asof)asof.textContent=raw?.asof||raw?.result?.asof||raw?.result?.timestamp||'最新快照';loadIntradayIc()}catch(e){el.innerHTML=empty('暂无分时快照','行业排名与市场曲线接口尚未就绪')}}
async function refreshIntraday(){try{const raw=await api('/intraday/latest');state.intradayLatest=raw;const el=document.querySelector('#intraday-output');if(el)el.innerHTML=raw?.available?intradayResult(raw.result||raw):empty('暂无分时动态结果','运行后显示买入窗口、卖出条件与稳定性');bindIntradayInteractions();await loadIntradayAnalytics();await loadPaperAccount();toast('分时结果已刷新')}catch(e){toast('读取分时结果失败：'+e.message,'error')}}
async function submitPosition(e){e.preventDefault();const code=(document.querySelector('#position-code')?.value||'').trim().toUpperCase();const shares=Number(document.querySelector('#position-shares')?.value);const price=Number(document.querySelector('#position-price')?.value);const date=document.querySelector('#position-date')?.value;if(!code||!(shares>0)||!(price>0)||!date){toast('请填写股票、股数、成本价和买入日期','error');return}try{await api('/intraday/positions',{method:'POST',body:JSON.stringify({ts_code:code,shares,entry_price:price,entry_date:date})});document.querySelector('#position-form-state').textContent='已记录纸上持仓 · 正在刷新卖出提醒';await refreshIntraday()}catch(err){toast('保存模拟持仓失败：'+err.message,'error')}}
function bindIntradayInteractions(){const out=document.querySelector('#intraday-output');if(out&&!out.dataset.bound){out.dataset.bound='1';out.addEventListener('click',e=>{const sel=e.target.closest('[data-intraday-select]');const use=e.target.closest('[data-intraday-use]');const code=sel?.dataset.intradaySelect||use?.dataset.intradayUse;if(!code)return;const row=(intradayRows(intradayPayload(state.intradayLatest)).find(x=>String(x.ts_code)===code)||intradayPayload(state.intradayLatest).buy_candidates?.find(x=>String(x.ts_code)===code));if(sel){const d=out.querySelector('#intraday-selected-detail');if(d)d.innerHTML=intradayStockDetail(row||{ts_code:code})+icStockBlock(code)}if(use){document.querySelector('#position-code').value=code;const p=Number(row?.last_close);if(p>0)document.querySelector('#position-price').value=p.toFixed(3);document.querySelector('#position-code').focus()}})}const _pf=document.querySelector('#intraday-position-form');if(_pf&&!_pf.dataset.bound){_pf.dataset.bound='1';_pf.addEventListener('submit',submitPosition)}const dl=document.querySelector('#intraday-codes');if(dl&&!dl.dataset.bound){const rows=intradayRows(intradayPayload(state.intradayLatest));dl.innerHTML=rows.slice(0,100).map(r=>`<option value="${esc(r.ts_code)}">${esc(r.name||'')}</option>`).join('');dl.dataset.bound='1'}}

function miniTrend(vals){const v=vals||[];const nums=v.filter(x=>x!=null).map(Number);if(nums.length<2)return '<span class="muted">—</span>';const lo=Math.min(0,...nums),hi=Math.max(0,...nums),span=hi-lo||1;const zy=19-(0-lo)*15/span;let d='',prev=false;v.forEach((x,i)=>{if(x==null){prev=false;return}const X=(i*64/Math.max(v.length-1,1)).toFixed(1),Y=(19-(Number(x)-lo)*15/span).toFixed(1);d+=(prev?' L':' M')+X+','+Y;prev=true});return `<svg class="ic-spark" viewBox="0 0 64 22" role="img" aria-label="IC 趋势"><path d="M0 ${zy.toFixed(1)}H64" class="ic-zero"/><path d="${d}" class="ic-line"/></svg>`}
function renderIntradayIcOverall(){const j=state.intradayIc;if(!j||!j.available)return '<div class="notice muted">近10日 RankIC 统计加载中（首次聚合约需一分钟）…</div>';const rows=(j.overall||[]).map(o=>({signal_date:o.date,ic:o.ic,dir:o.dir_acc}));return `<div class="ic-overall"><div class="chart-title">近 ${j.window_days} 个信号日 RankIC 与方向准确率 <span>${j.overall_mean_ic!=null?'均值 IC '+num(j.overall_mean_ic,3):''}</span></div>${factorLineChart(rows,[['ic','RankIC','var(--cyan)'],['dir','方向准确率','var(--amber)']])}<small class="muted">${esc(j.label_definition||'')}${j.label_check?` · 面板标签对账 corr=${num(j.label_check.corr,4)}（n=${j.label_check.n}）`:''}</small></div>`}
async function loadIntradayIc(){try{const j=await api('/intraday/ic-trend',{timeout:180000});state.intradayIc=j;const el=document.querySelector('#intraday-ic-overall');if(el)el.innerHTML=renderIntradayIcOverall();if(state.page==='intraday_predict')intradayIndustryPanel()}catch(e){const el=document.querySelector('#intraday-ic-overall');if(el)el.innerHTML='<div class="notice muted">近10日 RankIC 统计加载失败：'+esc(e.message)+'</div>'}}
function icStockBlock(code){const j=state.intradayIc;if(!j||!j.available)return '';const s=j.stocks?.[String(code).trim()];if(!s||!s.p?.length)return '';const rows=s.p.map((p,i)=>{const a=s.a[i]??0;const bar=v=>{const w=Math.min(52,Math.abs(v)*2200+4);return `<i class="${v>=0?'up':'down'}" style="width:${w.toFixed(0)}px" title="${pct(v)}"></i>`};return `<div class="ic-pair-row"><span>${esc(s.d[i]||'')}</span><em title="预测 ${pct(p)}">${bar(p)}</em><em title="实际 ${pct(a)}">${bar(a)}</em></div>`}).join('');return `<div class="ic-stock-block"><div class="ic-stock-head"><b>近 ${s.n} 日信号质量</b><span class="pill ${s.mean_ic>0?'ok':'bad'}">IC ${num(s.mean_ic,3)}</span><span class="pill ${s.dir_acc>=.5?'ok':'bad'}">方向准确率 ${pct(s.dir_acc)}</span></div><div class="ic-pair-head"><span>信号日</span><em>预测</em><em>实际</em></div>${rows}<small class="muted">柱长=|收益|；红=正、绿=负；实际口径：次日首个10:00 bar收盘/信号15:00收盘-1</small></div>`}
function renderHistory(){return shell('历史行情','过去30个交易日的全市场与行业成交趋势，聚合自规范30分钟面板（研究用途）。',`<div class="panel"><div class="panel-head"><h2>市场成交概览</h2><span class="muted" id="vh-asof">自动读取最新面板</span></div><div id="vh-body">${state.volumeHistory?volumeHistoryBody(state.volumeHistory):empty('加载中','正在聚合30日面板成交量（首次约需十几秒）')}</div></div>`)}
async function loadVolumeHistory(){if(state.volumeHistory){fillVolumeHistory();return}try{const j=await api('/market/volume-history',{timeout:150000});state.volumeHistory=j&&j.available?j:{available:false,reason:j&&j.reason||'读取失败'};fillVolumeHistory()}catch(e){const el=document.querySelector('#vh-body');if(el)el.innerHTML='<div class="notice error">历史成交数据读取失败：'+esc(e.message)+'</div>'}}
function fillVolumeHistory(){const el=document.querySelector('#vh-body');if(el)el.innerHTML=state.volumeHistory&&state.volumeHistory.available?volumeHistoryBody(state.volumeHistory):empty('暂无历史成交',state.volumeHistory&&state.volumeHistory.reason||'');}
const VH_PALETTE=['var(--cyan)','var(--amber)','var(--green)','#9d7bff','#48e2a3','#ff9f6e'];
function volumeHistoryBody(j){const days=j.dates||[];const mkt=j.market||[];const amts=mkt.map(m=>Number(m.amount)/1e8);const last=amts[amts.length-1],avg=amts.reduce((s,v)=>s+v,0)/(amts.length||1);const volLast=(Number(mkt[mkt.length-1]?.volume)||0)/1e8;const names=Object.keys(j.industries||{});if(!state.volumeSel||![...state.volumeSel].every(n=>names.includes(n)))state.volumeSel=new Set(names.slice(0,3));const sel=names.filter(n=>state.volumeSel.has(n));if(!state.vhDay||!days.includes(state.vhDay))state.vhDay=days[days.length-1]||null;const di=days.indexOf(state.vhDay);const hi=Math.max(...amts,0),lo=Math.min(...amts,0),span=hi-lo||1;const bw=Math.max(4,Math.floor(530/days.length))-3;const bars=amts.map((v,i)=>{const h=8+(v-lo)*120/span;const x=(46+i*(532/days.length)).toFixed(1);return `<rect x="${x}" y="${(150-h).toFixed(1)}" width="${bw}" height="${h.toFixed(1)}" rx="2" class="vh-bar" data-tip="${esc(days[i])} · ${num(v,0)} 亿元 · ${num((Number(mkt[i]?.volume)||0)/1e8,2)} 亿手 · ${mkt[i]?.stocks??'—'} 只"/>`}).join('');const chips=names.map(n=>`<button class="vh-chip ${state.volumeSel.has(n)?'on':''}" data-vh-ind="${esc(n)}">${esc(n)}</button>`).join('');const rows=days.map((d,i)=>{const r={signal_date:d};sel.forEach(n=>{r[n]=j.industries[n][i]});return r});const series=sel.map((n,i)=>[n,n,VH_PALETTE[i%VH_PALETTE.length]]);const mret=j.market_ret&&j.market_ret[di]!=null?`<span>当日全市场等权 <b class="${j.market_ret[di]>=0?'red':'green'}">${pct(j.market_ret[di])}</b></span>`:'';return `<div class="kpi-grid compact">${metricCard('最新日成交额',num(last,0)+' 亿','近 '+days.length+' 个交易日','cyan')}${metricCard('区间日均成交额',num(avg,0)+' 亿','半年来最活跃参照','')}${metricCard('最新日成交量',num(volLast,2)+' 亿手','全市场 30 分钟 bar 加总','green')}${metricCard('行业映射覆盖',pct(j.industry_coverage??0),'代码→行业（最新预测快照）','')}</div>${streaksBlock(j)}<div class="panel-head" style="margin-top:12px"><h3>每日行业横向比较</h3><span class="muted">半径=成交量 · 颜色=涨跌（红涨绿跌） · <label class="inline-field">日期 <select id="vh-day">${days.map(d=>`<option value="${d}" ${d===state.vhDay?'selected':''}>${d}</option>`).join('')}</select></label> ${mret}</span></div><div id="vh-bubble">${vhBubbleSvg(j,di)}</div><div class="chart-title" style="margin-top:12px">全市场日成交额（亿元） <span>${esc(days[0]||'')} → ${esc(days.at(-1)||'')}</span></div><svg viewBox="0 0 620 170" class="stock-chart" role="img" aria-label="全市场成交额"><path d="M46 150H590M46 80H590M46 14H590" class="gridline"/>${bars}<text x="4" y="20">${num(hi,0)}</text><text x="4" y="154">${num(lo,0)}</text></svg><div class="panel-head" style="margin-top:12px"><h3>行业成交趋势</h3><span class="muted">点击行业切换（最多 6 个）</span></div><div id="vh-chips" class="chip-row">${chips}</div><div id="vh-chart">${series.length?factorLineChart(rows,series):empty('未选择行业','点击上方标签')}</div>`}
function streaksBlock(j){const st=j.streaks;if(!st)return '';if(st.error)return `<div class="notice warn">连板统计失败：${esc(st.error)}</div>`;const inds=(st.industries||[]).filter(r=>r.chain_stocks.length||r.limit_today>0||r.up_streak>=2).slice(0,18);const chains=st.stocks||[];const maxChain=chains.length?chains[0].chain:0;if(!inds.length)return '';const rows=inds.map(r=>{const chips=r.chain_stocks.slice(0,6).map(c=>`<span class="lb-chip" data-tip="${esc(c.name)} · ${esc(r.industry)} · 连续 ${c.chain} 板">${esc(c.name)}<b>${c.chain}板</b></span>`).join('')||'<span class="muted">—</span>';const heatMax=Math.max(...r.heat,1);const heat=(r.heat||[]).map((v,hi)=>`<i style="height:${Math.max(1,v/heatMax*16).toFixed(0)}px" data-tip="${esc((j.dates||[])[hi]||'')} · ${esc(r.industry)} 涨停 ${v} 家"></i>`).join('');return `<tr><td>${esc(r.industry)}</td><td>${r.limit_today?`<b class="red">${r.limit_today}</b>`:'<span class="muted">0</span>'}</td><td class="${r.ret_today==null?'':(r.ret_today>=0?'red':'green')}">${pct(r.ret_today)}</td><td>${r.up_streak>=2?`<b>${r.up_streak} 日</b> <small class="${r.up_cum>=0?'red':'green'}">累计 ${pct(r.up_cum)}</small>`:'<span class="muted">—</span>'}</td><td>${chips}</td><td><span class="lb-heat">${heat}</span></td></tr>`}).join('');return `<div class="panel-head" style="margin-top:12px"><h3>连板与板块连续走强</h3><span class="muted">截至 ${esc(st.asof)} · 全市场今日涨停 <b class="red">${st.market_limit_today}</b> 家 · 连板股 ${chains.length} 只${maxChain?` · 最高 <b>${maxChain} 连板</b>`:''}</span></div><div class="table-wrap"><table><thead><tr><th>板块</th><th>今日涨停</th><th>板块涨幅</th><th>连续走强</th><th>连板股</th><th>近30日涨停热度</th></tr></thead><tbody>${rows}</tbody></table></div><small class="muted">排序：连板股多 → 涨停多 → 连续收涨久；涨停阈值 主板≈10%/创业·科创≈20%/北交所≈30%（15:00 收盘对上一交易日收盘）；今日未收盘时以最新已落盘 bar 计。看持续走强的板块，弱化单日轮动。</small>`}
function vhBubbleSvg(j,di){const days=j.dates||[];const day=days[di];if(day==null)return empty('暂无数据','没有可用交易日');const daily=j.industry_daily||{};const pts=Object.entries(daily).filter(([n])=>n!=='其余行业合计').map(([n,v])=>({n,ret:v.ret?.[di],amt:v.amount?.[di],vol:v.volume?.[di]})).filter(p=>p.ret!=null&&p.amt!=null&&p.vol>0).sort((a,b)=>b.vol-a.vol).slice(0,30);if(!pts.length)return empty('该日无行业行情','映射或价格数据缺失');const vmax=Math.max(...pts.map(p=>p.vol),1);const R=v=>4+Math.sqrt(v/vmax)*42;const placed=[];const inb=(x,y,r)=>x-r>4&&x+r<616&&y-r>4&&y+r<226;function spot(r){for(let t=0;t<900;t++){const a=t*2.39996;const rad=5*Math.sqrt(t);const x=310+rad*1.3*Math.cos(a),y=113+rad*0.9*Math.sin(a);if(!inb(x,y,r))continue;if(placed.every(p=>(p.x-x)**2+(p.y-y)**2>=(p.r+r+3)**2)){placed.push({x,y,r});return{x,y}}}for(let y=16;y<218;y+=16)for(let x=18;x<602;x+=16){if(inb(x,y,r)&&placed.every(p=>(p.x-x)**2+(p.y-y)**2>=(p.r+r+3)**2)){placed.push({x,y,r});return{x,y}}}return null}
const cir=pts.map(p=>{const r=R(p.vol);const pos=spot(r);if(!pos)return '';const up=p.ret>=0;const tip=`${p.n} · 涨跌 ${up?'+':''}${pct(p.ret)} · 成交额 ${num(p.amt/1e8,0)} 亿 · 成交量 ${num(p.vol/1e8,2)} 亿手`;const lab=r>=17?`<text x="${pos.x.toFixed(1)}" y="${(pos.y+(r>=24?-2:3)).toFixed(1)}" text-anchor="middle" class="vh-inlabel">${esc(p.n.length>5?p.n.slice(0,5):p.n)}</text>${r>=24?`<text x="${pos.x.toFixed(1)}" y="${(pos.y+10).toFixed(1)}" text-anchor="middle" class="vh-inlabel dim">${up?'+':''}${pct(p.ret)}</text>`:''}`:'';return `<circle cx="${pos.x.toFixed(1)}" cy="${pos.y.toFixed(1)}" r="${r.toFixed(1)}" fill="${up?'var(--red)':'var(--green)'}" fill-opacity=".5" stroke="${up?'var(--red)':'var(--green)'}" data-tip="${tip}"/>${lab}`}).join('');return `<svg viewBox="0 0 620 230" class="stock-chart" role="img" aria-label="行业气泡图">${cir}</svg><small class="muted">${esc(day)} · 气泡半径=成交量，红涨绿跌，大圆集中在中心 · 悬停查看涨跌幅与成交额 · 显示当日成交量前 ${pts.length} 个板块</small>`}
document.addEventListener('change',e=>{if(e.target&&e.target.id==='vh-day'){state.vhDay=e.target.value;const body=document.querySelector('#vh-body');if(body&&state.volumeHistory)body.innerHTML=volumeHistoryBody(state.volumeHistory)}},true);
document.addEventListener('click',e=>{const b=e.target.closest('[data-vh-ind]');if(!b)return;const n=b.dataset.vhInd;const j=state.volumeHistory;if(!j)return;if(state.volumeSel.has(n))state.volumeSel.delete(n);else{if(state.volumeSel.size>=6){toast('最多同时显示 6 个行业','error');return}state.volumeSel.add(n)}const body=document.querySelector('#vh-body');if(body){body.innerHTML=volumeHistoryBody(j)}},true);

// global hover tooltip (native svg <title> is slow/unreliable)
(function(){let tip=null;const ensure=()=>{if(!tip){tip=document.createElement('div');tip.id='global-tip';document.body.appendChild(tip)}return tip};document.addEventListener('mouseover',e=>{const t=e.target.closest?e.target.closest('[data-tip]'):null;if(!t)return;ensure().textContent=t.dataset.tip;tip.style.display='block'});document.addEventListener('mousemove',e=>{if(tip&&tip.style.display==='block'){tip.style.left=Math.min(e.clientX+14,window.innerWidth-tip.offsetWidth-8)+'px';tip.style.top=Math.min(e.clientY+16,window.innerHeight-tip.offsetHeight-8)+'px'}});document.addEventListener('mouseout',e=>{const t=e.target.closest?e.target.closest('[data-tip]'):null;if(t&&tip&&(!e.relatedTarget||e.relatedTarget!==tip))tip.style.display='none'});})();

function paperAccountBlock(){const a=state.paperAccount;if(!a)return '<div class="notice muted">纸上账户加载中…</div>';const pos=a.positions||[],tr=a.trades||[],st=a.stats||{};const posRows=pos.map(p=>{const up=Number(p.return)>=0;return `<tr><td>${esc(p.name||p.ts_code)}<small>${esc(p.ts_code)}</small></td><td>${num(p.shares,0)}</td><td>${num(p.entry_px,2)}</td><td>${num(p.last_price,2)}</td><td class="${up?'red':'green'}">${pct(p.return)}<small> ${num(p.float_pnl,0)} 元</small></td><td>${num(p.market_value,0)}</td><td><span class="pill ${p.action&&p.action!=='HOLD'?'bad':''}">${esc(p.action||'HOLD')}</span></td><td class="acct-actions"><button class="btn primary" data-ptrade-sell="${esc(p.id)}" data-ptrade-price="${num(p.last_price,3)}" data-ptrade-code="${esc(p.ts_code)}">卖出</button><button class="btn ghost" data-ptrade-cancel="${esc(p.id)}" title="取消错误录入，退款且不计盈亏">取消</button></td></tr>`}).join('');const trRows=tr.slice(0,20).map(t=>{const up=Number(t.pnl)>=0;return `<tr><td>${esc(t.exit_day||'')}</td><td>${esc(t.name||t.ts_code)}<small>${esc(t.ts_code)}</small></td><td>${num(t.shares,0)}</td><td>${num(t.entry_px,2)}</td><td>${num(t.exit_px,2)}</td><td class="${up?'red':'green'}"><b>${num(t.pnl,0)}</b><small> ${pct(t.ret)}</small></td><td>${esc(t.reason||'')}</td></tr>`}).join('');return `<div class="kpi-grid compact">${metricCard('本金',num(a.capital,0)+' 元','纸上资金，不涉实盘','cyan')}${metricCard('可用现金',num(a.cash,0)+' 元','买入扣减 · 平仓回补','')}${metricCard('持仓市值',num(a.market_value,0)+' 元',pos.length+' 只持仓','green')}${metricCard('总资产',num(a.total_asset,0)+' 元',(a.total_asset-a.capital>=0?'+':'')+num(a.total_asset-a.capital,0)+' vs 本金',a.total_asset>=a.capital?'green':'amber')}${metricCard('已实现盈亏',(st.total_pnl>=0?'+':'')+num(st.total_pnl,0)+' 元',st.n_trades?`平仓 ${st.n_trades} 笔`:'暂无平仓',st.total_pnl>=0?'green':'amber')}${metricCard('胜率',st.win_rate!=null?pct(st.win_rate):'—',st.n_trades?`${st.n_wins} 胜 ${st.n_losses} 负 · 盈亏比 ${st.profit_factor??'—'}`:'待交易','cyan')}</div>${pos.length?`<div class="table-wrap"><table><thead><tr><th>持仓</th><th>股数</th><th>成本</th><th>现价</th><th>浮盈</th><th>市值</th><th>建议</th><th>操作</th></tr></thead><tbody>${posRows}</tbody></table></div>`:empty('暂无持仓','下方录入，或在预测表点“录入持仓”')}<div class="panel-head" style="margin-top:12px"><h3>平仓记录</h3><span class="muted">最近 20 笔 · ${st.n_trades||0} 笔全部</span></div>${tr.length?`<div class="table-wrap"><table><thead><tr><th>平仓日</th><th>股票</th><th>股数</th><th>买入</th><th>卖出</th><th>盈亏</th><th>原因</th></tr></thead><tbody>${trRows}</tbody></table></div>`:empty('暂无平仓记录','点持仓行的“卖出”后计入')}<div class="actions acct-tools"><label class="inline-field">本金 <input id="paper-capital" type="number" min="1000" step="1000" value="${num(a.capital,0)}"></label>${btn('保存本金','paper-capital-save','btn ghost')}${btn('重置账户','paper-reset','btn danger')}</div><small class="muted">买入扣现金、卖出回补现金并计入盈亏；“取消”=退款不计盈亏。单位元/股，不含费用；纸上研究记录，绝不下实盘订单。</small>`}
function renderPaperAccount(){const el=document.querySelector('#paper-account');if(el)el.innerHTML=paperAccountBlock()}
async function loadPaperAccount(){try{const r=await api('/intraday/account');state.paperAccount=r?.account||null}catch(e){state.paperAccount={error:e.message}}renderPaperAccount()}
document.addEventListener('click',async e=>{const sell=e.target.closest('[data-ptrade-sell]');if(sell){try{const r=await api(`/intraday/positions/${sell.dataset.ptradeSell}/sell`,{method:'POST',body:JSON.stringify({price:Number(sell.dataset.ptradePrice)||undefined})});state.paperAccount=r?.account||state.paperAccount;renderPaperAccount();toast(r?.message||'已平仓');refreshIntraday()}catch(err){toast('平仓失败：'+err.message,'error')}return}const cancel=e.target.closest('[data-ptrade-cancel]');if(cancel){try{const r=await api(`/intraday/positions/${cancel.dataset.ptradeCancel}`,{method:'DELETE'});state.paperAccount=r?.account||state.paperAccount;renderPaperAccount();toast(r?.message||'已取消')}catch(err){toast('取消失败：'+err.message,'error')}return}if(e.target.closest('#paper-capital-save')){const v=Number(document.querySelector('#paper-capital')?.value);if(!(v>0)){toast('本金需为正数','error');return}try{const r=await api('/intraday/account',{method:'PUT',body:JSON.stringify({capital:v})});state.paperAccount=r?.account||state.paperAccount;renderPaperAccount();toast(r?.message||'本金已更新')}catch(err){toast(err.message,'error')}return}const rs=e.target.closest('#paper-reset');if(rs){if(rs.dataset.armed!=='1'){rs.dataset.armed='1';rs.textContent='再点一次确认重置';setTimeout(()=>{if(document.contains(rs)&&rs.dataset.armed==='1'){rs.dataset.armed='0';rs.textContent='重置账户'}},4000);return}try{const v=Number(document.querySelector('#paper-capital')?.value)||1000000;const r=await api('/intraday/account',{method:'PUT',body:JSON.stringify({capital:v,reset:true})});state.paperAccount=r?.account||state.paperAccount;renderPaperAccount();toast(r?.message||'账户已重置')}catch(err){toast(err.message,'error')}}});

async function loadMarketWave(){try{state.marketWave=await api('/market_wave',{timeout:15000})}catch(e){state.marketWave={available:false,reason:e.message}}renderMarketWave()}
function renderMarketWave(){const el=document.querySelector('#market-wave-output');if(!el)return;const m=state.marketWave;if(!m?.available){el.innerHTML=empty('暂无大盘浪型数据',m?.reason||'运行 market_wave_factor.py --refresh');return}
const s=m.summary;const daily=(m.daily||[]).map(r=>({signal_date:r.date,p_impulse:r.p_impulse,p_fast:r.p_fast,label:r.label,csi300:(r.csi300_pos==null?null:r.csi300_pos/100),sse:(r.sse_pos==null?null:r.sse_pos/100)}));
el.innerHTML=`<div class="kpi-grid">${metricCard('P(推动浪)',pct(s.p_impulse),esc(s.phase)+' · 已持续 '+esc(s.days_in_phase)+' 天',s.phase_code===1?'red':'green')}${metricCard('拟合方式',s.auc_insample!=null?('AUC '+s.auc_insample):'纯规则·零拟合',(s.auc_insample!=null?'历史样本内拟合，仅供复盘':'规则倾向值，非校准上涨概率'),'cyan')}${metricCard('阶段延续性','约 '+esc(s.avg_phase_days)+' 天/段','近 250 日翻转 '+esc(s.flips_250d)+' 次','amber')}${metricCard('数据截至',esc(s.date||'—'),'EMA α='+esc(s.alpha)+' · 概率平滑防跳变','')}</div><div class="spaced"><h3>P(推动浪) 每日概率 与 指数同尺度比对（虚线=50%分界；红=平滑，黄=敏感，灰=真值浪段，青/蓝=两指数120日高低区间位置%）</h3>${interactiveFactorChart(daily,[['p_impulse','P(推动浪) 平滑(α0.9)','var(--red)'],['p_fast','P(推动浪) 敏感(快速规则)','var(--amber)'],['label','事后真值(浪段)','var(--muted2)'],['csi300','沪深300·120日位置','var(--cyan)'],['sse','上证指数·120日位置','#60a5fa']],true,0.5)}</div><p class="muted">规则读数：${Object.entries(s.features||{}).map(([k,v])=>esc(k)+'='+esc(v)).join(' · ')}。今日投票：${Object.entries(s.feat_today||{}).map(([k,v])=>esc(k)+'='+esc(v)).join(' · ')}。方法：${esc(s.method)}；P≥50% 判推动浪，平滑用于减小跳变；灰色浪段为事后复盘，不是实时信号。全历史 corr(P,真值)=${esc(s.corr_truth??'—')}（上升腿 ${esc(s.truth_days?.up??'—')} 天 / 下降腿 ${esc(s.truth_days?.down??'—')} 天）；当前窗口若只有单一状态，相关性无定义。</p>`;
el.querySelectorAll('.ifchart').forEach(b=>ifcRender(b))}
const fo=document.querySelector('#factor-output');if(fo&&fo.querySelector('#gate-chart'))renderGateChart(fo);

function gateSeries(daily,scoreMap,alpha){const sorted=[...daily].sort((a,b)=>String(a.signal_date).localeCompare(String(b.signal_date)));let es=null;const out=[];
for(const r of sorted){const raw=scoreMap[String(r.signal_date)];const sc=(raw!=null&&Number.isFinite(Number(raw)))?Number(raw):null;let gate=gatePrevSafe(es);
if(sc!=null){gate=es==null?(sc>=0?1:0):(es>=0?1:0);es=es==null?sc:alpha*es+(1-alpha)*sc}
out.push({signal_date:r.signal_date,gate_ema:(es==null?null:Math.round(es*10000)/10000),gate_exp:gate})}
return out}
function gatePrevSafe(){return 0}
function renderGateChart(el){const holder=el.querySelector('#gate-chart');if(!holder)return;const daily=(state.factorLatest?.result?.daily_metrics)||state.factorLatest?.daily_metrics||[];
if(!daily.length||!state.marketWave?.available){holder.innerHTML=empty(!state.marketWave?.available?'等待大盘浪型数据':'等待因子评估数据','');return}
const scoreMap={};state.marketWave.daily.forEach(r=>{scoreMap[String(r.date)]=(r.score!=null&&r.score!=='')?Number(r.score):(r.p_impulse!=null?Number(r.p_impulse)*2-1:null)});
const alpha=Number(state.gateAlpha||0.65);
const rows=gateSeries(daily,scoreMap,alpha);
holder.innerHTML=interactiveFactorChart(rows,[['gate_ema','EMA门控值','var(--cyan)'],['gate_exp','当日敞口','var(--green)']],false);
holder.querySelectorAll('.ifchart').forEach(b=>ifcRender(b))}
document.addEventListener('change',e=>{const sel=e.target.closest?e.target.closest('.gate-alpha'):null;if(!sel)return;state.gateAlpha=Number(sel.value);const el=document.querySelector('#factor-output');if(el)renderGateChart(el)});

async function loadChanPhase(){try{state.chan=await api('/chan_phase',{timeout:15000})}catch(e){state.chan={available:false,reason:e.message}}renderChan()}
function renderChan(){const el=document.querySelector('#chan-output');if(!el)return;const m=state.chan;if(!m?.available){el.innerHTML=empty('暂无缠论数据',m?.reason||'运行 chan_phase_engine.py');return}
const s=m.summary;const daily=(m.daily||[]).map(r=>({signal_date:r.date,phase:r.phase}));
el.innerHTML=`<div class="kpi-grid">${metricCard('当前阶段',esc(s.phase),'已持续 '+esc(s.days_in_phase)+' 天',s.phase_code===1?'red':s.phase_code===-1?'green':'amber')}${metricCard('阶段用途','按所选规则执行','上涨/非下跌/不门控，分别回测','')}${metricCard('信号口径','逐日冻结','收盘确认 · 下一交易日执行','cyan')}${metricCard('背驰信号','底 '+esc(s.bottom_div_count)+' / 顶 '+esc(s.top_div_count),'最近底背驰 '+esc(s.last_bottom_div||'—'),'amber')}</div><div class="spaced"><h3>缠论阶段（1=上涨 0=震荡 -1=下跌）</h3>${interactiveFactorChart(daily,[['phase','阶段','var(--cyan)']],false,0.5)}</div><p class="muted">${esc(s.method)}。旧版历史收益与低延迟结论已撤下，收益和回撤以新资金账户回测为准。</p>`;
el.querySelectorAll('.ifchart').forEach(b=>ifcRender(b))}

function chanPhaseLabel(v){return ({'1':'上涨','0':'盘整','-1':'下跌'})[String(v)]??'—'}
function chanPct(v,d=1){return v==null?'—':(Number(v)*100).toFixed(d)+'%'}
function chanNum(v,d=3){return v==null?'—':Number(v).toFixed(d)}
async function loadChanMulti(){const combo=document.querySelector('#chan-combo')?.value||state.chanCombo||'5F-30F-D';state.chanCombo=combo;try{state.chanMulti=await api('/chan_multi?combo='+encodeURIComponent(combo),{timeout:30000})}catch(e){state.chanMulti={available:false,reason:e.message,combo}}renderChanMulti()}
function renderChanMulti(){const el=document.querySelector('#chan-multi-output');if(!el)return;const m=state.chanMulti;if(!m?.available){el.innerHTML=empty('暂无多级别缠论数据',m?.reason||'先在服务器运行 chan_multi_engine.py');return}
const h=m.headline||{},l=m.latest||{},live=l.live||{},cov=m.coverage||{},levels=l.levels||{};
const levelOrder=(m.combo||'').split('-').filter(Boolean);
const levelEntries=levelOrder.map(name=>[name,levels[name]]).filter(([,x])=>x);
const latestMs=l.date?new Date(l.date+'T15:00:00').getTime():null;
const levelRows=levelEntries.map(([name,x])=>{let lag=null;if(latestMs&&x.bar_dt){const t=new Date(x.bar_dt.replace(' ','T')).getTime();if(Number.isFinite(t))lag=Math.max(0,Math.round((latestMs-t)/86400000));}return `<tr><td><b>${esc(name)}</b></td><td>${esc(x.bar_dt||'—')}${(name==='5F'||name==='30F')&&lag>0?` <span class="pill bad">滞后${lag}天</span>`:''}</td><td><span class="pill ${x.phase===1?'ok':x.phase===-1?'bad':''}">${chanPhaseLabel(x.phase)}</span></td><td>${chanNum(x.trend_score)}</td><td>${chanNum(x.pivot_zd,2)} – ${chanNum(x.pivot_zg,2)}</td><td>${chanNum(x.pivot_pos,2)}</td><td>${x.last_dir>0?'上笔':x.last_dir<0?'下笔':'—'}</td><td>${x.div===1?'底背驰':x.div===-1?'顶背驰':'—'}</td><td>${x.pivot_strokes??'—'}</td></tr>`}).join('');
const liveProba=live.proba||{};const livePred=live.pred;
const confusion=(h.confusion||[]).map((row,i)=>`<tr><td>${chanPhaseLabel([-1,0,1][i])}</td>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('');
const yearly=(h.yearly||[]).map(y=>`<tr><td>${y.year}</td><td>${chanPct(y.balanced_accuracy)}</td><td>${chanPct(y.recall?.['-1'])}</td><td>${chanPct(y.recall?.['0'])}</td><td>${chanPct(y.recall?.['1'])}</td><td>${y.n}</td></tr>`).join('');
const grid=(m.grid||[]).slice().sort((a,b)=>a.horizon-b.horizon||a.theta-b.theta).map(c=>{const mm=c.models||{};return `<tr><td>${c.horizon}</td><td>${chanPct(c.theta)}</td><td><b>${chanPct(mm.hgb_logit?.balanced_accuracy)}</b></td><td>${chanPct(mm.hier_logit?.balanced_accuracy)}</td><td>${chanPct(mm.combined_logit?.balanced_accuracy)}</td><td>${chanPct(mm.chan_logit?.balanced_accuracy)}</td><td>${chanPct(mm.price_logit?.balanced_accuracy)}</td><td>${chanPct(mm.rule?.balanced_accuracy)}</td><td>${chanPct(mm.momentum?.balanced_accuracy)}</td><td>${chanPct(mm.single_chan?.balanced_accuracy)}</td></tr>`}).join('');
const rows=(m.daily||[]).map(r=>({date:r.date,align:r.align_score,pred:r.pred_hier_full,label:r.label}));
const chart=rows.length?interactiveFactorChart(rows,[['align','级别共振得分','var(--cyan)'],['pred','预测阶段','var(--amber)'],['label','实际阶段','var(--green)']],false):empty('暂无日度序列');
const sourceRows=Object.entries(m.data_sources||{}).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${esc(v)}</td></tr>`).join('');
const ci=h.bootstrap?.ba?`${chanPct(h.bootstrap.ba.low)} – ${chanPct(h.bootstrap.ba.high)}`:'—';
el.innerHTML=`<div class="kpi-grid">${metricCard('当前阶段',chanPhaseLabel(levels.D?.phase??levels.W?.phase),'D 中枢 '+chanNum(levels.D?.pivot_zd,0)+' – '+chanNum(levels.D?.pivot_zg,0),levels.D?.phase===1?'red':levels.D?.phase===-1?'green':'amber')}${metricCard('未来阶段预测',chanPhaseLabel(livePred),'HGB 模型 · P(涨) '+chanPct(liveProba['1'])+' / P(跌) '+chanPct(liveProba['-1']),livePred===1?'red':livePred===-1?'green':'amber')}${metricCard('Balanced Acc',chanPct(h.balanced_accuracy),'95%CI '+ci+' · HGB '+chanPct(h.hgb_balanced_accuracy??h.balanced_accuracy)+' / 分层 '+chanPct(h.hier_balanced_accuracy)+' / Logit '+chanPct(h.combined_balanced_accuracy)+' · n='+(h.n??'—'),'cyan')}${metricCard('规则基线',chanPct(h.rule_balanced_accuracy),'单级别 '+chanPct(h.single_chan_balanced_accuracy)+' · 动量 '+chanPct(h.momentum_balanced_accuracy),'')}</div><div class="notice">口径：${esc(h.label_mode==='path'?'未来'+h.horizon+'日路径型（端点超过 ±'+chanPct(h.theta)+' 且逆向回撤受限）':'端点收益')}；OOS ${esc(h.test_start)} → ${esc(h.test_end)}；数据 ${esc(cov.start)} → ${esc(cov.end)}。${esc(h.bootstrap?.delta?('相对规则 ΔBA 95%CI '+chanPct(h.bootstrap.delta.low)+' – '+chanPct(h.bootstrap.delta.high)):'')}${h.endpoint_comparison?.metrics?('；端点标签 BA '+chanPct(h.endpoint_comparison.metrics.balanced_accuracy)):''}</div><div class="spaced"><h3>三级别状态（最新）</h3><div class="table-wrap"><table><thead><tr><th>级别</th><th>Bar 时间</th><th>阶段</th><th>趋势分</th><th>中枢 ZD–ZG</th><th>中枢位置</th><th>末笔</th><th>背驰</th><th>中枢笔数</th></tr></thead><tbody>${levelRows}</tbody></table></div></div><div class="grid grid-2 spaced"><div><h3>混淆矩阵（行=实际，列=预测）</h3><div class="table-wrap"><table><thead><tr><th>实际\\预测</th><th>下跌</th><th>盘整</th><th>上涨</th></tr></thead><tbody>${confusion}</tbody></table></div></div><div><h3>逐年 Balanced Acc</h3><div class="table-wrap"><table><thead><tr><th>年份</th><th>BA</th><th>跌召回</th><th>盘召回</th><th>涨召回</th><th>n</th></tr></thead><tbody>${yearly}</tbody></table></div></div></div><div class="spaced"><h3>级别共振与阶段序列</h3>${chart}</div><div class="spaced"><h3>Horizon × 阈值网格（balanced accuracy）</h3><div class="table-wrap"><table><thead><tr><th>H</th><th>θ</th><th>HGB</th><th>分层</th><th>多因子Logit</th><th>缠论Logit</th><th>价格Logit</th><th>规则</th><th>动量</th><th>单级别</th></tr></thead><tbody>${grid}</tbody></table></div></div><details class="spaced"><summary>数据来源与覆盖</summary><div class="table-wrap"><table><thead><tr><th>级别</th><th>来源</th></tr></thead><tbody>${sourceRows}</tbody></table></div></details><p class="muted">因果口径：每个交易日收盘后读取已完成的三级别状态，标签使用未来收益，训练只使用标签已结束的样本；中枢为前三笔重叠区间，末笔可被更极端同型分型替换但历史状态不重写。5F 数据自 2020 年（Baostock 前复权篮子），因此 5F–30F–D 的 OOS 起点晚于 30F–D–W 与 D–W–M。</p>`;
el.querySelectorAll('.ifchart').forEach(b=>ifcRender(b))}

